window.BOOK={"key":"qawaidusul","app":"mutoon","lsk":"mutoon_qawaidusul_v1","title":"قواعد الأصول ومعاقد الفصول","unitWord":"فقرة","sub":"أصول الفقه الحنبلي · صفي الدين عبد المؤمن البغدادي (ت ٧٣٩هـ) · ٢٢ بابًا","source":"قواعد الأصول ومعاقد الفصول، ت. د. أنس اليتامى ود. عبد العزيز العيدان (ركائز ١٤٣٩هـ، مشكول، على نسختين خطيتين) = https://shamela.ws/book/19 · قوبل بـ: قوبل كلمةً كلمةً بنشرة المستودع في الشاملة (OpenITI ShamAY0037576، طبعة قديمة غير مشكولة) — انظر qawaidusul-sources.md","note":"النص المشكول من طبعة ركائز المحققة على نسختين خطيتين، مقابَلًا كلمةً كلمةً بسكربت بنشرة قديمة غير مشكولة (مستودع الشاملة). أُبقي لفظ ركائز في مواضع الخلاف، وأُكمل شكل بضع كلمات، وتقسيم الفصول داخل الأبواب من فهرس المحقق، وكل ذلك في تقرير المصادر.","chapters":[{"id":"qa1","title":"مُقَدِّمَةُ الْمُصَنِّفِ","units":[{"id":"qa1_1","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ١","segs":[["matn","أَحْمَدُ اللَّهَ عَلَى إِحْسَانِهِ وَإِفْضَالِهِ، كَمَا يَنْبَغِي لِكَرَمِ وَجْهِهِ وَعِزِّ جَلَالِهِ، وَأُصَلِّي عَلَى نَبِيِّهِ الْمُكَمَّلِ بِإِرْسَالِهِ، الْمُؤَيَّدِ فِي أَقْوَالِهِ وَأَفْعَالِهِ، وَعَلَى جَمِيعِ صَحْبِهِ وَآلِهِ."]]},{"id":"qa1_2","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٢","segs":[["matn","هَذِهِ «قَوَاعِدُ الْأُصُولِ وَمَعَاقِدُ الْفُصُولِ» مِنْ كِتَابِيَ الْمُسَمَّى بِ«تَحْقِيقِ الْأَمَلِ» مُجَرَّدَةً عَنِ الدَّلَائِلِ، مِنْ غَيْرِ إِخْلَالٍ بِشَيْءٍ مِنَ الْمَسَائِلِ؛ تَذْكِرَةً لِلطَّالِبِ الْمُسْتَبِينِ، وَتَبْصِرَةً لِلرَّاغِبِ الْمُسْتَعِينِ."]]},{"id":"qa1_3","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٣","segs":[["matn","وَبِاللَّهِ أَسْتَعِينُ، وَعَلَيْهِ أَتَوَكَّلُ، وَهُوَ حَسْبِي وَنِعْمَ الْوَكِيلُ الْمُعِينُ. أُصُولُ الْفِقْهِ: مَعْرِفَةُ دَلَائِلِ الْفِقْهِ إِجْمَالًا، وَكَيْفِيَّةِ الِاسْتِفَادَةِ مِنْهَا، وَحَالِ الْمُسْتَفِيدِ؛ وَهُوَ الْمُجْتَهِدُ. وَالْفِقْهُ: الْفَهْمُ."]]},{"id":"qa1_4","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٤","segs":[["matn","وَاصْطِلَاحًا: مَعْرِفَةُ أَحْكَامِ الشَّرْعِ الْمُتَعَلِّقَةِ بِأَفْعَالِ الْعِبَادِ. وَالْأَصْلُ: مَا يَنْبَنِي عَلَيْهِ غَيْرُهُ. فَأُصُولُ الْفِقْهِ: أَدِلَّتُهُ. وَالْغَرَضُ مِنْهُ: مَعْرِفَةُ: كَيْفِيَّةِ اقْتِبَاسِ الْأَحْكَامِ. وَالْأَدِلَّةِ. وَحَالِ الْمُقْتَبِسِ. وَذَلِكَ ثَلَاثَةُ أَبْوَابٍ."]]}],"group":"مُقَدِّمَةُ الْمُصَنِّفِ"},{"id":"qa2","title":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ","units":[{"id":"qa2_1","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١","segs":[["matn","الْحُكْمُ: قِيلَ فِيهِ حُدُودٌ، أَسْلَمُهَا مِنَ النَّقْضِ وَالِاضْطِرَابِ: أَنَّهُ قَضَاءُ الشَّارِعِ عَلَى الْمَعْلُومِ بِأَمْرٍ مَا، نُطْقًا أَوِ اسْتِنْبَاطًا. وَالْحَاكِمُ: هُوَ اللَّهُ سُبْحَانَهُ، لَا حَاكِمَ سِوَاهُ."]]},{"id":"qa2_2","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ٢","segs":[["matn","وَالرَّسُولُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُبَلِّغٌ وَمُبَيِّنٌ لِمَا حَكَمَ بِهِ. وَالْمَحْكُومُ عَلَيْهِ: الْإِنْسَانُ الْمُكَلَّفُ. وَالْأَحْكَامُ قِسْمَانِ: تَكْلِيفِيَّةٌ، وَهِيَ خَمْسَةٌ: وَاجِبٌ: يَقْتَضِي الثَّوَابَ عَلَى الْفِعْلِ، وَالْعِقَابَ عَلَى التَّرْكِ."]]},{"id":"qa2_3","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ٣","segs":[["matn","وَيَنْقَسِمُ مِنْ حَيْثُ الْفِعْلُ: إِلَى مُعَيَّنٍ: لَا يَقُومُ غَيْرُهُ مَقَامَهُ؛ كَالصَّلَاةِ، وَالصَّوْمِ، وَنَحْوِهِمَا. وَإِلَى مُبْهَمٍ فِي أَقْسَامٍ مَحْصُورَةٍ؛ يُجْزِئُ وَاحِدٌ مِنْهَا؛ كَخِصَالِ الْكَفَّارَةِ."]]},{"id":"qa2_4","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ٤","segs":[["matn","وَمِنْ حَيْثُ الْوَقْتُ: إِلَى مُضَيَّقٍ: وَهُوَ مَا تَعَيَّنَ لَهُ وَقْتٌ لَا يَزِيدُ عَلَى فِعْلِهِ؛ كَصَوْمِ رَمَضَانَ."]]},{"id":"qa2_5","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ٥","segs":[["matn","وَإِلَى مُوَسَّعٍ: وَهُوَ مَا كَانَ وَقْتُهُ الْمُعَيَّنُ يَزِيدُ عَلَى فِعْلِهِ؛ كَالصَّلَاةِ وَالْحَجِّ، فَهُوَ مُخَيَّرٌ فِي الْإِتْيَانِ بِهِ فِي أَحَدِ أَجْزَائِهِ."]]},{"id":"qa2_6","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ٦","segs":[["matn","فَلَوْ أَخَّرَ، وَمَاتَ قَبْلَ ضِيقِ الْوَقْتِ؛ لَمْ يَعْصِ؛ لِجَوَازِ التَّأْخِيرِ، بِخِلَافِ مَا بَعْدَهُ. وَمِنْ حَيْثُ الْفَاعِلُ: إِلَى فَرْضِ عَيْنٍ: وَهُوَ مَا لَا تَدْخُلُهُ النِّيَابَةُ مَعَ الْقُدْرَةِ وَعَدَمِ الْحَاجَةِ؛ كَالْعِبَادَاتِ الْخَمْسِ."]]},{"id":"qa2_7","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ٧","segs":[["matn","وَفَرْضِ كِفَايَةٍ: وَهُوَ مَا يُسْقِطُهُ فِعْلُ الْبَعْضِ مَعَ الْقُدْرَةِ وَعَدَمِ الْحَاجَةِ؛ كَالْعِيدِ وَالْجِنَازَةِ. وَالْغَرَضُ مِنْهُ: وُجُودُ الْفِعْلِ فِي الْجُمْلَةِ. فَلَوْ تَرَكَهُ الْكُلُّ: أَثِمُوا؛ لِفَوَاتِ الْغَرَضِ."]]},{"id":"qa2_8","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ٨","segs":[["matn","وَمَا لَا يَتِمُّ الْوَاجِبُ إِلَّا بِهِ: إِمَّا غَيْرُ مَقْدُورٍ لِلْمُكَلَّفِ؛ كَالْقُدْرَةِ، وَالْيَدِ فِي الْكِتَابَةِ، وَاسْتِكْمَالِ عَدَدِ الْجُمُعَةِ: فَلَا حُكْمَ لَهُ."]]},{"id":"qa2_9","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ٩","segs":[["matn","وَإِمَّا مَقْدُورٌ؛ كَالسَّعْيِ إِلَى الْجُمُعَةِ، وَصَوْمِ جُزْءٍ مِنَ اللَّيْلِ، وَغَسْلِ جُزْءٍ مِنَ الرَّأْسِ: فَهُوَ وَاجِبٌ؛ لِتَوَقُّفِ التَّمَامِ عَلَيْهِ."]]},{"id":"qa2_10","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٠","segs":[["matn","فَلَوِ اشْتَبَهَتْ أُخْتُهُ بِأَجْنَبِيَّةٍ، أَوْ مَيْتَةٌ بِمُذَكَّاةٍ: وَجَبَ الْكَفُّ؛ تَحَرُّجًا عَنْ مُوَاقَعَةِ الْحَرَامِ."]]},{"id":"qa2_11","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١١","segs":[["matn","فَلَوْ وَطِئَ وَاحِدَةً، أَوْ أَكَلَ، فَصَادَفَ الْمُبَاحَ: لَمْ يَكُنْ مُوَاقِعًا لِلْحَرَامِ بَاطِنًا، لَكِنْ ظَاهِرًا؛ لِفِعْلِ مَا لَيْسَ لَهُ. وَمَنْدُوبٌ: وَهُوَ مَا يَقْتَضِي الثَّوَابَ عَلَى الْفِعْلِ، لَا الْعِقَابَ عَلَى التَّرْكِ."]]},{"id":"qa2_12","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٢","segs":[["matn","وَبِمَعْنَاهُ: الْمُسْتَحَبُّ. وَالسُّنَّةُ: وَهِيَ الطَّرِيقَةُ وَالسِّيرَةُ، لَكِنْ تَخْتَصُّ بِمَا فُعِلَ لِلْمُتَابَعَةِ فَقَطْ. وَالنَّفْلُ: وَهُوَ الزِّيَادَةُ عَلَى الْوَاجِبِ."]]},{"id":"qa2_13","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٣","segs":[["matn","وَقَدْ سَمَّى الْقَاضِي مَا لَا يَتَمَيَّزُ مِنْ ذَلِكَ؛ كَالطُّمَأْنِينَةِ فِي الرُّكُوعِ وَالسُّجُودِ: وَاجِبًا، بِمَعْنَى: أَنَّهُ يُثَابُ عَلَيْهَا ثَوَابَ الْوَاجِبِ؛ لِعَدَمِ التَّمَيُّزِ. وَخَالَفَهُ أَبُو الْخَطَّابِ. وَالْفَضِيلَةُ، وَالْأَفْضَلُ: كَالْمَنْدُوبِ."]]},{"id":"qa2_14","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٤","segs":[["matn","وَمَحْظُورٌ: وَهُوَ لُغَةً الْمَمْنُوعُ. وَالْحَرَامُ بِمَعْنَاهُ. وَهُوَ ضِدُّ الْوَاجِبِ: مَا يُعَاقَبُ عَلَى فِعْلِهِ، وَيُثَابُ عَلَى تَرْكِهِ."]]},{"id":"qa2_15","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٥","segs":[["matn","فَلِذَلِكَ: يَسْتَحِيلُ كَوْنُ الشَّيْءِ الْوَاحِدِ بِالْعَيْنِ وَاجِبًا حَرَامًا؛ كَالصَّلَاةِ فِي الدَّارِ الْمَغْصُوبَةِ، فِي أَصَحِّ الرِّوَايَتَيْنِ. وَعِنْدَ مَنْ صَحَّحَهَا: النَّهْيُ إِمَّا أَنْ يَرْجِعَ: إِلَى ذَاتِ الْمَنْهِيِّ عَنْهُ: فَيُضَادُّ وُجُوبَهُ."]]},{"id":"qa2_16","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٦","segs":[["matn","أَوْ إِلَى صِفَتِهِ؛ كَالصَّلَاةِ فِي السُّكْرِ، وَالْحَيْضِ، وَالْأَمَاكِنِ السَّبْعَةِ، وَالْأَوْقَاتِ الْخَمْسَةِ: فَسَمَّاهُ أَبُو حَنِيفَةَ: فَاسِدًا. وَعِنْدَنَا، وَعِنْدَ الشَّافِعِيِّ: أَنَّهُ مِنَ الْقِسْمِ الْأَوَّلِ؛ لِأَنَّ الْمَنْهِيَّ عَنْهُ نَفْسُ هَذِهِ الصَّلَاةِ، وَلِذَلِكَ بَطَلَتْ."]]},{"id":"qa2_17","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٧","segs":[["matn","أَوْ لَا إِلَى وَاحِدٍ مِنْهُمَا؛ كَلُبْسِ الْحَرِيرِ، فَإِنَّ الْمُصَلِّيَ فِيهِ جَامِعٌ بَيْنَ الْقُرْبَةِ وَالْمَكْرُوهِ بِالْجِهَتَيْنِ: فَتَصِحُّ. وَمَكْرُوهٌ."]]},{"id":"qa2_18","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٨","segs":[["matn","وَهُوَ ضِدُّ الْمَنْدُوبِ: مَا يَقْتَضِي تَرْكُهُ الثَّوَابَ، وَلَا عِقَابَ عَلَى فِعْلِهِ؛ كَالْمَنْهِيِّ عَنْهُ نَهْيَ تَنْزِيهٍ. وَمُبَاحٌ. وَالْجَائِزُ، وَالْحَلَالُ: بِمَعْنَاهُ. وَهُوَ: مَا لَا يَتَعَلَّقُ بِفِعْلِهِ أَوْ تَرْكِهِ ثَوَابٌ وَلَا عِقَابٌ."]]},{"id":"qa2_19","label":"الْحُكْمُ وَالْأَحْكَامُ التَّكْلِيفِيَّةُ · ١٩","segs":[["matn","وَقَدِ اخْتُلِفَ فِي حُكْمِ الْأَعْيَانِ الْمُنْتَفَعِ بِهَا قَبْلَ الشَّرْعِ: فَعِنْدَ أَبِي الْخَطَّابِ، وَالتَّمِيمِيِّ: الْإِبَاحَةُ، كَأَبِي حَنِيفَةَ، فَلِذَلِكَ أَنْكَرَ بَعْضُ الْمُعْتَزِلَةِ شَرْعِيَّتَهُ. وَعِنْدَ الْقَاضِي، وَابْنِ حَامِدٍ، وَبَعْضِ الْمُعْتَزِلَةِ: الْحَظْرُ. وَتَوَقَّفَ الْخَرَزِيُّ، وَالْأَكْثَرُونَ."]]}],"group":"الْبَابُ الْأَوَّلُ فِي الْحُكْمِ وَلَوَازِمِهِ"},{"id":"qa3","title":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ","units":[{"id":"qa3_1","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ١","segs":[["matn","وَوَضْعِيَّةٌ، وَهِيَ أَرْبَعَةٌ: أَحَدُهَا: مَا يَظْهَرُ بِهِ الْحُكْمُ، وَهُوَ نَوْعَانِ: عِلَّةٌ: - إِمَّا عَقْلِيَّةٌ؛ كَالْكَسْرِ لِلِانْكِسَارِ. - أَوْ شَرْعِيَّةٌ: قِيلَ: إِنَّهَا الْمَعْنَى الَّذِي عَلَّقَ الشَّرْعُ الْحُكْمَ عَلَيْهِ."]]},{"id":"qa3_2","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ٢","segs":[["matn","وَقِيلَ: الْبَاعِثُ لَهُ عَلَى إِثْبَاتِهِ، وَهَذَا أَوْلَى. وَسَبَبٌ، وَقَدِ اسْتَعْمَلَهُ الْفُقَهَاءُ: - فِيمَا يُقَابِلُ الْمُبَاشِرَ؛ كَالْحَفْرِ مَعَ التَّرْدِيَةِ. - وَفِي عِلَّةِ الْعِلَّةِ؛ كَالرَّمْيِ فِي الْقَتْلِ لِلْمَوْتِ."]]},{"id":"qa3_3","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ٣","segs":[["matn","- وَفِي الْعِلَّةِ بِدُونِ شَرْطِهَا؛ كَالنِّصَابِ بِدُونِ الْحَوْلِ. - وَفِي الْعِلَّةِ نَفْسِهَا؛ كَالْقَتْلِ لِلْقِصَاصِ، وَلِذَلِكَ سَمَّوُا الْوَصْفَ الْوَاحِدَ مِنْ أَوْصَافِ الْعِلَّةِ جُزْءَ السَّبَبِ."]]},{"id":"qa3_4","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ٤","segs":[["matn","وَمِنْ تَوَابِعِهِمَا: الشَّرْطُ: وَهُوَ مَا يَتَوَقَّفُ عَلَى وُجُودِهِ: - إِمَّا الْحُكْمُ؛ كَالْإِحْصَانِ لِلرَّجْمِ، وَيُسَمَّى: شَرْطَ الْحُكْمِ. - أَوْ عَمَلُ الْعِلَّةِ: وَهُوَ شَرْطُ الْعِلَّةِ؛ كَالْإِحْصَانِ مَعَ الزِّنَى."]]},{"id":"qa3_5","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ٥","segs":[["matn","فَيُفَارِقُ الْعِلَّةَ مِنْ حَيْثُ إِنَّهُ لَا يَلْزَمُ الْحُكْمُ مِنْ وُجُودِهِ. وَهُوَ: عَقْلِيٌّ: كَالْحَيَاةِ لِلْعِلْمِ. وَلُغَوِيٌّ: كَالْمُقْتَرِنِ بِحُرُوفِهِ. وَشَرْعِيٌّ: كَالطَّهَارَةِ لِلصَّلَاةِ. وَالْمَانِعُ: عَكْسُهُ، وَهُوَ مَا يَتَوَقَّفُ السَّبَبُ أَوِ الْحُكْمُ عَلَى عَدَمِهِ."]]},{"id":"qa3_6","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ٦","segs":[["matn","- فَمَانِعُ السَّبَبِ: كَالدَّيْنِ مَعَ مِلْكِ النِّصَابِ. - وَمَانِعُ الْحُكْمِ: وَهُوَ الْوَصْفُ الْمُنَاسِبُ لِنَقِيضِ الْحُكْمِ؛ كَالْمَعْصِيَةِ بِالسَّفَرِ الْمُنَافِي لِلتَّرَخُّصِ."]]},{"id":"qa3_7","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ٧","segs":[["matn","ثُمَّ قِيلَ: هُمَا مِنْ جُمْلَةِ السَّبَبِ؛ لِتَوَقُّفِهِ عَلَى وُجُودِ الشَّرْطِ وَعَدِمِ الْمَانِعِ. وَلَيْسَ بِشَيْءٍ. الثَّانِي: الصَّحِيحُ، لُغَةً: الْمُسْتَقِيمُ. وَاصْطِلَاحًا: فِي الْعِبَادَاتِ: مَا أَجْزَأَ وَأَسْقَطَ الْقَضَاءَ. وَعِنْدَ الْمُتَكَلِّمِينَ: مَا وَافَقَ الْأَمْرَ."]]},{"id":"qa3_8","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ٨","segs":[["matn","وَفِي الْعُقُودِ: مَا أَفَادَ حُكْمَهُ الْمَقْصُودَ مِنْهُ. وَالْفَاسِدُ لُغَةً: الْمُخْتَلُّ. وَاصْطِلَاحًا: مَا لَيْسَ بِصَحِيحٍ. وَمِثْلُهُ: الْبَاطِلُ. وَخَصَّ أَبُو حَنِيفَةَ بِاسْمِ الْفَاسِدِ: مَا شُرِعَ بِأَصْلِهِ وَمُنِعَ بِوَصْفِهِ، وَالْبَاطِلِ: مَا مُنِعَ بِهِمَا."]]},{"id":"qa3_9","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ٩","segs":[["matn","وَهُوَ اصْطِلَاحٌ. وَالنُّفُوذُ لُغَةً: الْمُجَاوَزَةُ. وَاصْطِلَاحًا: التَّصَرُّفُ الَّذِي لَا يَقْدِرُ مُتَعَاطِيهِ عَلَى رَفْعِهِ. وَقِيلَ: كَالصَّحِيحِ. وَالْأَدَاءُ: فِعْلُ الشَّيْءِ فِي وَقْتِهِ. وَالْإِعَادَةُ: فِعْلُهُ ثَانِيًا لِخَلَلٍ أَوْ غَيْرِهِ."]]},{"id":"qa3_10","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ١٠","segs":[["matn","وَالْقَضَاءُ: فِعْلُهُ بَعْدَ خُرُوجِ وَقْتِهِ. وَقِيلَ: إِلَّا صَوْمَ الْحَائِضِ بَعْدَ رَمَضَانَ. وَلَيْسَ بِشَيْءٍ. الثَّالِثُ: الْمُنْعَقِدُ، وَأَصْلُهُ: الِالْتِفَافُ. وَاصْطِلَاحًا: إِمَّا: ارْتِبَاطٌ بَيْنَ قَوْلَيْنِ مَخْصُوصَيْنِ؛ كَالْإِيجَابِ وَالْقَبُولِ."]]},{"id":"qa3_11","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ١١","segs":[["matn","أَوِ: اللُّزُومُ؛ كَانْعِقَادِ الصَّلَاةِ وَالنَّذْرِ بِالدُّخُولِ. وَأَصْلُ اللُّزُومِ: الثُّبُوتُ. وَاللَّازِمُ: مَا يَمْتَنِعُ عَلَى أَحَدِ الْمُتَعَاقِدَيْنِ فَسْخُهُ بِمُفْرَدِهِ. وَالْجَائِزُ: مَا لَا يَمْتَنِعُ. وَالْحَسَنُ: مَا لِفَاعِلِهِ أَنْ يَفْعَلَهُ. وَالْقَبِيحُ: مَا لَيْسَ لَهُ."]]},{"id":"qa3_12","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ١٢","segs":[["matn","الرَّابِعُ: الْعَزِيمَةُ، وَالرُّخْصَةُ. وَأَصْلُ الْعَزِيمَةِ: الْقَصْدُ الْمُؤَكَّدُ. وَالرُّخْصَةُ: السُّهُولَةُ. وَاصْطِلَاحًا: الْعَزِيمَةُ: الْحُكْمُ الثَّابِتُ مِنْ غَيْرِ مُخَالَفَةِ دَلِيلٍ شَرْعِيٍّ. وَالرُّخْصَةُ: إِبَاحَةُ الْمَحْظُورِ مَعَ قِيَامِ سَبَبِ الْحَظْرِ."]]},{"id":"qa3_13","label":"الْأَحْكَامُ الْوَضْعِيَّةُ وَلَوَازِمُ الْحُكْمِ · ١٣","segs":[["matn","وَقِيلَ: مَا ثَبَتَ عَلَى خِلَافِ دَلِيلٍ شَرْعِيٍّ لِمُعَارِضٍ رَاجِحٍ. كَ تَيَمُّمِ الْمَرِيضِ لِمَرَضِهِ. وَأَكْلِ الْمَيْتَةِ لِلْمُضْطَرِّ. لِقِيَامِ سَبَبِ الْحَظْرِ؛ لِوُجُودِ الْمَاءِ، وَخُبْثِ الْمَحَلِّ. وَالْعَرَايَا مِنْ صُوَرِ الْمُزَابَنَةِ."]]}],"group":"الْبَابُ الْأَوَّلُ فِي الْحُكْمِ وَلَوَازِمِهِ"},{"id":"qa4","title":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ","units":[{"id":"qa4_1","label":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ · ١","segs":[["matn","أَصْلُ الدَّلَالَةِ: الْإِرْشَادُ. وَاصْطِلَاحًا: قِيلَ: مَا يُتَوَصَّلُ بِهِ إِلَى مَعْرِفَةِ مَا لَا يُعْلَمُ فِي مُسْتَقِرِّ الْعَادَةِ اضْطِرَارًا، عِلْمًا أَوْ ظَنًّا. وَالدَّلِيلُ يُرَادُ بِهِ: إِمَّا الدَّالُّ؛ كَدَلِيلِ الطَّرِيقِ."]]},{"id":"qa4_2","label":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ · ٢","segs":[["matn","أَوْ مَا يُسْتَدَلُّ بِهِ مِنْ نَصٍّ أَوْ غَيْرِهِ. وَيُرَادِفُهُ أَلْفَاظٌ، مِنْهَا: الْبُرْهَانُ، وَالْحُجَّةُ، وَالسُّلْطَانُ، وَالْآيَةُ؛ وَهَذِهِ تُسْتَعْمَلُ فِي الْقَطْعِيَّاتِ، وَقَدْ تُسْتَعْمَلُ فِي الظَّنِّيَّاتِ. وَالْأَمَارَةُ، وَالْعَلَامَةُ؛ وَتُسْتَعْمَلُ فِي الظَّنِّيَّاتِ فَقَطْ."]]},{"id":"qa4_3","label":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ · ٣","segs":[["matn","وَأُصُولُ الْأَدِلَّةِ أَرْبَعَةٌ: الْكِتَابُ. وَالسُّنَّةُ. وَالْإِجْمَاعُ. وَهِيَ سَمْعِيَّةٌ. وَيَتَفَرَّعُ عَنْهَا: الْقِيَاسُ. وَالِاسْتِدْلَالُ. وَالرَّابِعُ عَقْلِيٌّ: وَهُوَ اسْتِصْحَابُ الْحَالِ فِي النَّفْيِ الْأَصْلِيِّ الدَّالِّ عَلَى بَرَاءَةِ الذِّمَّةِ. فَالْكِتَابُ: كَلَامُ اللَّهِ عَزَّ وَجَلَّ."]]},{"id":"qa4_4","label":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ · ٤","segs":[["matn","وَهُوَ الْقُرْآنُ الْمَتْلُوُّ بِالْأَلْسِنَةِ، الْمَكْتُوبُ فِي الْمَصَاحِفِ، الْمَحْفُوظُ فِي الصُّدُورِ. وَهُوَ كَغَيْرِهِ مِنَ الْكَلَامِ فِي أَقْسَامِهِ: فَمِنْهُ حَقِيقَةٌ: وَهِيَ اللَّفْظُ الْمُسْتَعْمَلُ فِيمَا وُضِعَ لَهُ."]]},{"id":"qa4_5","label":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ · ٥","segs":[["matn","وَمَجَازٌ: وَهُوَ اللَّفْظُ الْمُسْتَعْمَلُ فِي غَيْرِ مَا وُضِعَ لَهُ عَلَى وَجْهٍ يَصِحُّ؛ كَ﴿جَنَاحَ الذُّلِّ﴾، وَ﴿يُرِيدُ أَنْ يَنْقَضَّ﴾."]]},{"id":"qa4_6","label":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ · ٦","segs":[["matn","وَمِنْهُ مَا اسْتُعْمِلَ فِي لُغَةٍ أُخْرَى: وَهُوَ الْمُعَرَّبُ؛ كَ﴿نَاشِئَةَ اللَّيْلِ﴾، وَهِيَ حَبَشِيَّةٌ، وَ«الْمِشْكَاةُ» هِنْدِيَّةٌ، وَ«الْإِسْتَبْرَقُ» فَارِسِيَّةٌ. وَقَالَ الْقَاضِي: الْكُلُّ عَرَبِيٌّ. وَفِيهِ: مُحْكَمٌ، وَمُتَشَابِهٌ. قَالَ الْقَاضِي: الْمُحْكَمُ: الْمُفَسَّرُ، وَالْمُتَشَابِهُ: الْمُجْمَلُ."]]},{"id":"qa4_7","label":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ · ٧","segs":[["matn","وَقَالَ ابْنُ عَقِيلٍ: الْمُتَشَابِهُ: مَا يَغْمُضُ عِلْمُهُ عَلَى غَيْرِ الْعُلَمَاءِ الْمُحَقِّقِينَ؛ كَالْآيَاتِ الْمُتَعَارِضَةِ. وَقِيلَ: الْحُرُوفُ الْمُقَطَّعَةُ. وَقِيلَ: الْمُحْكَمُ: الْوَعْدُ وَالْوَعِيدُ، وَالْحَرَامُ وَالْحَلَالُ. وَالْمُتَشَابِهُ: الْقَصَصُ، وَالْأَمْثَالُ."]]},{"id":"qa4_8","label":"الْأَدِلَّةُ، وَالْأَصْلُ الْأَوَّلُ: الْكِتَابُ · ٨","segs":[["matn","وَالصَّحِيحُ: أَنَّ الْمُتَشَابِهَ مَا يَجِبُ الْإِيمَانُ بِهِ، وَيَحْرُمُ تَأْوِيلُهُ؛ كَآيَاتِ الصِّفَاتِ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa5","title":"الْأَصْلُ الثَّانِي: السُّنَّةُ","units":[{"id":"qa5_1","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١","segs":[["matn","وَالسُّنَّةُ: مَا وَرَدَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ قَوْلٍ غَيْرِ الْقُرْآنِ، أَوِ فِعْلٍ، أَوْ تَقْرِيرٍ. فَالْقَوْلُ: حُجَّةٌ قَاطِعَةٌ يَجِبُ عَلَى مَنْ سَمِعَهُ الْعَمَلُ بِمُقْتَضَاهُ؛ لِدَلَالَةِ الْمُعْجِزِ عَلَى صِدْقِهِ."]]},{"id":"qa5_2","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢","segs":[["matn","وَأَمَّا الْفِعْلُ: فَمَا ثَبَتَ فِيهِ أَمْرُ الْجِبِلَّةِ؛ كَالْقِيَامِ، وَالْقُعُودِ، وَغَيْرِهِمَا: فَلَا حُكْمَ لَهُ. وَمَا ثَبَتَ خُصُوصُهُ بِهِ؛ كَقِيَامِ اللَّيْلِ: فَلَا شِرْكَةَ لِغَيْرِهِ فِيهِ."]]},{"id":"qa5_3","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٣","segs":[["matn","وَمَا فَعَلَهُ بَيَانًا: إِمَّا بِالْقَوْلِ: كَقَوْلِهِ: «صَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي». أَوْ بِالْفِعْلِ: كَقَطْعِ السَّارِقِ مِنَ الْكُوعِ. فَهُوَ مُعْتَبَرٌ اتِّفَاقًا فِي حَقِّ غَيْرِهِ. وَمَا سِوَى ذَلِكَ: فَالتَّشْرِيكُ."]]},{"id":"qa5_4","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٤","segs":[["matn","- فَإِنْ عُلِمَ حُكْمُهُ مِنَ الْوُجُوبِ وَالْإِبَاحَةِ وَغَيْرِهِمَا: فَكَذَلِكَ اتِّفَاقًا. - وَإِنْ لَمْ يُعْلَمْ؛ فَفِيهِ رِوَايَتَانِ: إِحْدَاهُمَا: أَنَّ حُكْمَهُ الْوُجُوبُ؛ كَقَوْلِ أَبِي حَنِيفَةَ، وَبَعْضِ الشَّافِعِيَّةِ."]]},{"id":"qa5_5","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٥","segs":[["matn","وَالْأُخْرَى: النَّدْبُ؛ لِثُبُوتِ رُجْحَانِ الْفِعْلِ دُونَ الْمَنْعِ مِنَ التَّرْكِ. وَقِيلَ: الْإِبَاحَةُ. وَتَوَقَّفَ الْمُعْتَزِلَةُ؛ لِلتَّعَارُضِ. وَالْوُجُوبُ أَحْوَطُ."]]},{"id":"qa5_6","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٦","segs":[["matn","وَأَمَّا تَقْرِيرُهُ: وَهُوَ تَرْكُ الْإِنْكَارِ عَلَى فِعْلِ فَاعِلٍ: فَإِنْ عُلِمَ عِلْمُهُ ذَلِكَ؛ كَالذِّمِّيِّ عَلَى فِطْرِهِ رَمَضَانَ: فَلَا حُكْمَ لَهُ. وَإِلَّا: دَلَّ عَلَى الْجَوَازِ."]]},{"id":"qa5_7","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٧","segs":[["matn","ثُمَّ الْعَالِمُ بِذَلِكَ مِنْهُ: بِالْمُبَاشَرَةِ؛ إِمَّا بِسَمَاعِ الْقَوْلِ، أَوْ رُؤْيَةِ الْفِعْلِ أَوِ التَّقْرِيرِ: فَقَاطِعٌ بِهِ."]]},{"id":"qa5_8","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٨","segs":[["matn","وَغَيْرُهُ إِنَّمَا يَصِلُ إِلَيْهِ بِطَرِيقِ الْخَبَرِ عَنِ الْمُبَاشِرِ: فَيَتَفَاوَتُ فِي قَطْعِيَّتِهِ بِتَفَاوُتِ طَرِيقِهِ؛ لِأَنَّ الْخَبَرَ يَدْخُلُهُ الصِّدْقُ وَالْكَذِبُ، وَلَا سَبِيلَ إِلَى الْقَطْعِ بِصِدْقِهِ لِعَدَمِ الْمُبَاشَرَةِ. وَالْخَبَرُ: يَنْقَسِمُ إِلَى تَوَاتُرٍ وَآحَادٍ."]]},{"id":"qa5_9","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٩","segs":[["matn","فَالتَّوَاتُرُ: إِخْبَارُ جَمَاعَةٍ لَا يُمْكِنُ تَوَاطُؤُهُمْ عَلَى الْكَذِبِ. وَشُرُوطُهُ ثَلَاثَةٌ: إِسْنَادُهُ إِلَى مَحْسُوسٍ: كَ«سَمِعْتُ»، أَوْ «رَأَيْتُ». لَا إِلَى اعْتِقَادٍ. وَاسْتِوَاءُ الطَّرَفَيْنِ وَالْوَاسِطَةِ فِي شَرْطِهِ. وَالْعَدَدُ: فَقِيلَ: أَقَلُّهُ اثْنَانِ. وَقِيلَ: أَرْبَعَةٌ."]]},{"id":"qa5_10","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٠","segs":[["matn","وَقِيلَ: خَمْسَةٌ. وَقِيلَ: عِشْرُونَ. وَقِيلَ: سَبْعُونَ. وَقِيلَ غَيْرُ ذَلِكَ."]]},{"id":"qa5_11","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١١","segs":[["matn","وَالصَّحِيحُ: لَا يَنْحَصِرُ فِي عَدَدٍ، بَلْ مَتَى أَخْبَرَ وَاحِدٌ بَعْدَ وَاحِدٍ حَتَّى يَخْرُجُوا بِالْكَثْرَةِ إِلَى حَدٍّ لَا يُمْكِنُ تَوَاطُؤُهُمْ عَلَى الْكَذِبِ؛ حَصَلَ الْقَطْعُ بِقَوْلِهِمْ. وَكَذَلِكَ يَحْصُلُ بِدُونِ: عَدَالَةِ الرُّوَاةِ. وَإِسْلَامِهِمْ."]]},{"id":"qa5_12","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٢","segs":[["matn","لِقَطْعِنَا بِوُجُودِ مِصْرَ. وَيَحْصُلُ الْعِلْمُ بِهِ. وَيَجِبُ تَصْدِيقُهُ: بِمُجَرَّدِهِ. وَغَيْرِهِ: بِدَلِيلٍ خَارِجِيٍّ. وَالْعِلْمُ الْحَاصِلُ بِهِ: ضَرُورِيٌّ عِنْدَ الْقَاضِي. وَنَظَرِيٌّ عِنْدَ أَبِي الْخَطَّابِ."]]},{"id":"qa5_13","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٣","segs":[["matn","وَإِفَادَةُ الْعِلْمِ فِي وَاقِعَةٍ، وَلِشَخْصٍ بِدُونِ قَرِينَةٍ: إِفَادَةٌ فِي غَيْرِهَا، أَوْ لِشَخْصٍ آخَرَ. وَالْآحَادُ: مَا لَمْ يَتَوَاتَرْ. وَالْعِلْمُ: لَا يَحْصُلُ بِهِ فِي إِحْدَى الرِّوَايَتَيْنِ، وَهِيَ قَوْلُ الْأَكْثَرِينَ، وَمُتَأَخِّرِي أَصْحَابِنَا."]]},{"id":"qa5_14","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٤","segs":[["matn","وَالْأُخْرَى: بَلَى، وَهُوَ قَوْلُ جَمَاعَةٍ مِنْ أَصْحَابِ الْحَدِيثِ وَالظَّاهِرِيَّةِ."]]},{"id":"qa5_15","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٥","segs":[["matn","وَقَدْ حُمِلَ ذَلِكَ مِنْهُمْ: عَلَى مَا نَقَلَهُ الْأَئِمَّةُ الْمُتَّفَقُ عَلَى عَدَالَتِهِمْ، وَتَلَقَّتْهُ الْأُمَّةُ بِالْقَبُولِ؛ لِقُوَّتِهِ بِذَلِكَ كَخَبَرِ الصَّحَابِيِّ، فَإِنْ لَمْ تَكُنْ قَرِينَةٌ، أَوْ عَارَضَهُ خَبَرٌ آخَرُ؛ فَلَيْسَ كَذَلِكَ."]]},{"id":"qa5_16","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٦","segs":[["matn","وَقَدْ أَنْكَرَ قَوْمٌ جَوَازَ التَّعَبُّدِ بِهِ عَقْلًا؛ لِاحْتِمَالِهِ. وَقَالَ أَبُو الْخَطَّابِ: يَقْتَضِيهِ. وَالْأَكْثَرُونَ: لَا يَمْتَنِعُ. فَأَمَّا سَمْعًا: فَيَجِبُ عِنْدَ الْجُمْهُورِ. وَخَالَفَ أَكْثَرُ الْقَدَرِيَّةِ، وَإِجْمَاعُ الصَّحَابَةِ عَلَى قَبُولِهِ يَرُدُّ ذَلِكَ."]]},{"id":"qa5_17","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٧","segs":[["matn","وَشُرُوطُ الرَّاوِي أَرْبَعَةٌ: الْإِسْلَامُ: فَلَا تُقْبَلُ رِوَايَةُ كَافِرٍ، وَلَوْ بِبِدْعَةٍ. إِلَّا الْمُتَأَوِّلَ إِذَا لَمْ يَكُنْ دَاعِيَةً، فِي ظَاهِرِ كَلَامِهِ. وَالتَّكْلِيفُ حَالَةَ الْأَدَاءِ. وَالضَّبْطُ: سَمَاعًا. وَأَدَاءً. وَالْعَدَالَةُ: فَلَا يُقْبَلُ مِنْ فَاسِقٍ."]]},{"id":"qa5_18","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٨","segs":[["matn","إِلَّا بِبِدْعَةٍ مُتَأَوِّلًا عِنْدَ أَبِي الْخَطَّابِ وَالشَّافِعِيِّ. وَالْمَجْهُولُ فِي شَرْطٍ مِنْهَا: لَا يُقْبَلُ، كَمَذْهَبِ الشَّافِعِيِّ. وَعَنْهُ: إِلَّا فِي الْعَدَالَةِ، كَمَذْهَبِ أَبِي حَنِيفَةَ. وَلَا يُشْتَرَطُ: ذُكُورِيَّتُهُ. وَلَا رُؤْيَتُهُ. وَلَا فِقْهُهُ."]]},{"id":"qa5_19","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ١٩","segs":[["matn","وَلَا مَعْرِفَةُ نَسَبِهِ. وَيُقْبَلُ الْمَحْدُودُ فِي الْقَذْفِ إِنْ كَانَ شَاهِدًا. وَالصَّحَابَةُ كُلُّهُمْ عُدُولٌ بِإِجْمَاعِ الْمُعْتَبَرِينَ. وَالصَّحَابِيُّ: مَنْ صَحِبَهُ وَلَوْ سَاعَةً، أَوْ رَآهُ مُؤْمِنًا. وَتَثْبُتُ صُحْبَتُهُ: بِخَبَرِ غَيْرِهِ عَنْهُ."]]},{"id":"qa5_20","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٠","segs":[["matn","أَوْ خَبَرِهِ عَنْ نَفْسِهِ. وَغَيْرُ الصَّحَابِيِّ: لَا بُدَّ مِنْ تَزْكِيَتِهِ؛ كَالشَّهَادَةِ."]]},{"id":"qa5_21","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢١","segs":[["matn","وَالرِّوَايَةُ عَنْهُ: تَزْكِيَةٌ فِي رِوَايَةٍ، بِشَرْطِ أَنْ يُعْلَمَ مِنْ عَادَةِ الرَّاوِي أَوْ صَرِيحِ قَوْلِهِ أَنَّهُ لَا يَرْوِي إِلَّا عَنْ عَدْلٍ. وَالْحُكْمُ بِشَهَادَتِهِ أَقْوَى مِنْ تَزْكِيَتِهِ."]]},{"id":"qa5_22","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٢","segs":[["matn","وَالْجَرْحُ: نِسْبَةُ مَا تُرَدُّ بِهِ الشَّهَادَةُ. وَلَيْسَ تَرْكُ الْحُكْمِ بِشَهَادَةٍ مِنْهُ. وَيُقْبَلُ -كَالتَّزْكِيَةِ- مِنْ وَاحِدٍ. وَلَا يَجِبُ ذِكْرُ سَبَبِهِ. وَعَنْهُ: بَلَى. وَقِيلَ: يُسْتَفْسَرُ غَيْرُ الْعَالِمِ. وَيُقَدَّمُ عَلَى التَّعْدِيلِ. وَقِيلَ: الْأَكْثَرُ."]]},{"id":"qa5_23","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٣","segs":[["matn","وَأَمَّا أَلْفَاظُ الرِّوَايَةِ: فَمِنَ الصَّحَابِيِّ خَمْسَةٌ: أَقْوَاهَا: «سَمِعْتُهُ»، أَوْ «أَخْبَرَنِي»، أَوْ «شَافَهَنِي». ثُمَّ: «قَالَ كَذَا»؛ لِاحْتِمَالِ سَمَاعِهِ مِنْ غَيْرِهِ. ثُمَّ: «أَمَرَ»، أَوْ «نَهَى». ثُمَّ: «أُمِرْنَا»، أَوْ «نُهِينَا»؛ لِعَدَمِ تَعَيُّنِ الْآمِرِ."]]},{"id":"qa5_24","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٤","segs":[["matn","وَمِثْلُهُ: «مِنَ السُّنَّةِ». ثُمَّ: «كُنَّا نَفْعَلُ»، أَوْ «كَانُوا يَفْعَلُونَ». فَإِنْ أُضِيفَتْ إِلَى زَمَنِهِ: فَحُجَّةٌ؛ لِظُهُورِ إِقْرَارِهِ عَلَيْهِ. وَقَالَ أَبُو الْخَطَّابِ: «كَانُوا يَفْعَلُونَ» نَقْلٌ لِلْإِجْمَاعِ. خِلَافًا لِبَعْضِ الشَّافِعِيَّةِ."]]},{"id":"qa5_25","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٥","segs":[["matn","وَيُقْبَلُ قَوْلُهُ: «هَذَا الْخَبَرُ مَنْسُوخٌ» عِنْدَ أَبِي الْخَطَّابِ. وَيُرْجَعُ إِلَيْهِ فِي تَفْسِيرِهِ. وَلِغَيْرِهِ مَرَاتِبُ: أَعْلَاهَا: قِرَاءَةُ الشَّيْخِ عَلَيْهِ فِي مَعْرِضِ الْإِخْبَارِ، فَيَقُولُ: «حَدَّثَنِي»، أَوْ «أَخْبَرَنِي»، وَ«قَالَ»، وَ«سَمِعْتُهُ»."]]},{"id":"qa5_26","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٦","segs":[["matn","ثُمَّ: قِرَاءَتُهُ عَلَى الشَّيْخِ، فَيَقُولُ الشَّيْخُ: «نَعَمْ»، أَوْ يَسْكُتُ، خِلَافًا لِبَعْضِ الظَّاهِرِيَّةِ. فَيَقُولُ: «أَخْبَرَنَا»، أَوْ «حَدَّثَنَا» قِرَاءَةً عَلَيْهِ، لَا بِدُونِهِ، فِي رِوَايَةٍ."]]},{"id":"qa5_27","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٧","segs":[["matn","وَلَيْسَ لَهُ إِبْدَالُ إِحْدَى لَفْظَتَيِ الشَّيْخِ: بِ«حَدَّثَنَا» أَوْ «أَخْبَرَنَا» بِالْأُخْرَى، فِي رِوَايَةٍ. ثُمَّ: الْإِجَازَةُ، فَيَقُولُ: «أَجَزْتُ لَكَ رِوَايَةَ الْكِتَابِ الْفُلَانِيِّ»، أَوْ «مَسْمُوعَاتِي». وَالْمُنَاوَلَةُ: فَيُنَاوِلُهُ كِتَابًا، وَيَقُولُ: «ارْوِهِ عَنِّي»، فَيَقُولُ: «أَنْبَأَنَا»."]]},{"id":"qa5_28","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٨","segs":[["matn","وَإِنْ قَالَ: «أَخْبَرَنَا»؛ فَلَا بُدَّ مِنْ: «إِجَازَةً»، أَوْ «مُنَاوَلَةً». وَحُكِيَ عَنْ أَبِي حَنِيفَةَ وَأَبِي يُوسُفَ: مَنْعُ الرِّوَايَةِ بِهِمَا."]]},{"id":"qa5_29","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٢٩","segs":[["matn","وَلَا تَجُوزُ الرِّوَايَةُ بِقَوْلِهِ: «خُذْ هَذَا الْكِتَابَ»، أَوْ: «هُوَ سَمَاعِي»، بِدُونِ إِذْنِهِ فِيهِمَا. وَلَا وُجُودِهِ بِخَطِّهِ، بَلْ يَقُولُ: «وَجَدْتُ كَذَا»."]]},{"id":"qa5_30","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٣٠","segs":[["matn","وَمَتَى وَجَدَ سَمَاعَهُ بِخَطٍّ يُوثَقُ بِهِ، وَغَلَبَ عَلَى ظَنِّهِ: رَوَاهُ، وَإِنْ لَمْ يَذْكُرْهُ. خِلَافًا لِأَبِي حَنِيفَةَ. وَإِنْ شَكَّ: فَلَا. فَإِنْ أَنْكَرَ الشَّيْخُ الْحَدِيثَ، وَقَالَ: «لَا أَذْكُرُهُ»: لَمْ يَقْدَحْ."]]},{"id":"qa5_31","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٣١","segs":[["matn","وَمَنَعَ الْكَرْخِيُّ مِنْهُ. وَلَوْ زَادَ ثِقَةٌ فِيهِ لَفْظًا أَوْ مَعْنًى: قُبِلَتْ. فَإِنِ اتَّحَدَ الْمَجْلِسُ: فَالْأَكْثَرُ عِنْدَ أَبِي الْخَطَّابِ. وَالْمُثْبِتُ مَعَ التَّسَاوِي فِي الْعَدَدِ وَالْحِفْظِ وَالضَّبْطِ. وَقَالَ الْقَاضِي: رِوَايَتَانِ."]]},{"id":"qa5_32","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٣٢","segs":[["matn","وَلَا يَتَعَيَّنُ لَفْظُهُ، بَلْ يَجُوزُ بِالْمَعْنَى لِعَالِمٍ بِمُقْتَضَيَاتِ الْأَلْفَاظِ عِنْدَ الْجُمْهُورِ، فَيُبْدِلُ اللَّفْظَ بِمُرَادِفِهِ لَا بِغَيْرِهِ. وَمَنَعَ مِنْهُ بَعْضُ الْمُحَدِّثِينَ مُطْلَقًا. وَمَرَاسِيلُ الصَّحَابَةِ مَقْبُولَةٌ."]]},{"id":"qa5_33","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٣٣","segs":[["matn","وَقِيلَ: إِنْ عُلِمَ أَنَّهُ لَا يَرْوِي إِلَّا عَنْ صَحَابِيٍّ. وَفِي مَرَاسِيلِ غَيْرِهِمْ رِوَايَتَانِ: الْقَبُولُ، كَمَذْهَبِ أَبِي حَنِيفَةَ وَجَمَاعَةٍ مِنَ الْمُتَكَلِّمِينَ، اخْتَارَهَا الْقَاضِي. وَالْمَنْعُ، وَهُوَ قَوْلُ الشَّافِعِيِّ وَبَعْضِ الْمُحَدِّثِينَ وَالظَّاهِرِيَّةِ."]]},{"id":"qa5_34","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٣٤","segs":[["matn","وَخَبَرُ الْوَاحِدِ: فِيمَا تَعُمُّ بِهِ الْبَلْوَى: مَقْبُولٌ. خِلَافًا لِأَكْثَرِ الْحَنَفِيَّةِ. وَفِي الْحُدُودِ، وَمَا يَسْقُطُ بِالشُّبْهَةِ. خِلَافًا لِلْكَرْخِيِّ. وَفِيمَا يُخَالِفُ الْقِيَاسَ. وَحُكِيَ عَنْ مَالِكٍ: تَقْدِيمُ الْقِيَاسِ."]]},{"id":"qa5_35","label":"الْأَصْلُ الثَّانِي: السُّنَّةُ · ٣٥","segs":[["matn","وَقَالَ أَبُو حَنِيفَةَ: لَيْسَ بِحُجَّةٍ إِنْ خَالَفَ الْأُصُولَ أَوْ مَعْنَاهُ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa6","title":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ","units":[{"id":"qa6_1","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ١","segs":[["matn","ثُمَّ هَا هُنَا أَبْحَاثٌ يَشْتَرِكُ فِيهَا الْكِتَابُ وَالسُّنَّةُ مِنْ حَيْثُ إِنَّهَا لَفْظِيَّةٌ، مِنْهَا: اللُّغَاتُ تَوْقِيفِيَّةٌ؛ لِلدَّوْرِ. وَقِيلَ: اصْطِلَاحِيَّةٌ؛ لِامْتِنَاعِ فَهْمِ التَّوْقِيفِ بِدُونِهِ."]]},{"id":"qa6_2","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ٢","segs":[["matn","وَقَالَ الْقَاضِي: كِلَا الْقَوْلَيْنِ جَائِزٌ فِي الْجَمِيعِ، وَفِي الْبَعْضِ وَالْبَعْضِ."]]},{"id":"qa6_3","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ٣","segs":[["matn","أَمَّا الْوَاقِعُ: فَلَا دَلِيلَ عَلَيْهِ عَقْلِيٌّ وَلَا نَقْلِيٌّ، فَيَجُوزُ خَلْقُ الْعِلْمِ فِي الْإِنْسَانِ بِدَلَالَتِهَا عَلَى مُسَمَّيَاتِهَا، وَابْتِدَاءُ قَوْمٍ بِالْوَضْعِ عَلَى حَسَبِ الْحَاجَةِ وَيَتْبَعُهُمُ الْبَاقُونَ."]]},{"id":"qa6_4","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ٤","segs":[["matn","ثُمَّ قَالَ: وَيَجُوزُ أَنْ تُثْبَتَ الْأَسْمَاءُ قِيَاسًا؛ كَتَسْمِيَةِ النَّبِيذِ خَمْرًا كَقِيَاسِ التَّصْرِيفِ. وَمَنَعَهُ أَبُو الْخَطَّابِ، وَالْحَنَفِيَّةُ، وَبَعْضُ الشَّافِعِيَّةِ. وَالْكَلَامُ: هُوَ الْمُنْتَظِمُ مِنَ الْأَصْوَاتِ الْمَسْمُوعَةِ الْمُعْتَمِدَةِ عَلَى الْمَقَاطِعِ، وَهِيَ الْحُرُوفُ."]]},{"id":"qa6_5","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ٥","segs":[["matn","وَهُوَ: جَمْعُ كَلِمَةٍ، وَهِيَ اللَّفْظُ الْمَوْضُوعُ لِمَعْنًى. وَخَصَّ أَهْلُ الْعَرَبِيَّةِ الْكَلَامَ بِالْمُفِيدِ؛ وَهُوَ الْجُمَلُ الْمُرَكَّبَةُ مِنْ فِعْلٍ وَفَاعِلٍ، أَوْ مُبْتَدَأٍ وَخَبَرٍ. وَغَيْرُ الْمُفِيدِ: كَ«لَمْ»."]]},{"id":"qa6_6","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ٦","segs":[["matn","فَإِنِ اسْتُعْمِلَ فِي الْمَعْنَى الْمَوْضُوعِ لَهُ: فَهُوَ الْحَقِيقَةُ. إِنْ كَانَ بِوَضْعِ اللُّغَةِ: فَهِيَ اللُّغَوِيَّةُ. أَوْ بِالْعُرْفِ: فَالْعُرْفِيَّةُ؛ كَالدَّابَّةِ لِذَوَاتِ الْأَرْبَعِ. أَوْ بِالشَّرْعِ: فَالشَّرْعِيَّةُ؛ كَالصَّلَاةِ وَالزَّكَاةِ."]]},{"id":"qa6_7","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ٧","segs":[["matn","وَأَنْكَرَ قَوْمٌ: الشَّرْعِيَّةَ، وَقَالُوا: اللُّغَوِيُّ بَاقٍ، وَالزِّيَادَاتُ شُرُوطٌ. وَكُلٌّ يَتَعَيَّنُ بِاللَّافِظِ: فَمِنْ أَهْلِ اللُّغَةِ بِدُونِ الْقَرِينَةِ: اللُّغَوِيَّةُ. وَبِقَرِينَةِ الْعُرْفِ: الْعُرْفِيَّةُ. وَمِنْ أَهْلِ الشَّرْعِ: الشَّرْعِيَّةُ."]]},{"id":"qa6_8","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ٨","segs":[["matn","وَلَا يَكُونُ مُجْمَلًا، كَمَا حُكِيَ عَنِ الْقَاضِي وَبَعْضِ الشَّافِعِيَّةِ. وَإِنِ اسْتُعْمِلَ فِي غَيْرِ مَا وُضِعَ لَهُ: فَهُوَ الْمَجَازُ بِالْعَلَاقَةِ، وَهِيَ: إِمَّا اشْتِرَاكُهُمَا فِي مَعْنًى مَشْهُورٍ؛ كَالشَّجَاعَةِ فِي الْأَسَدِ."]]},{"id":"qa6_9","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ٩","segs":[["matn","أَوِ الِاتِّصَالِ؛ كَقَوْلِهِمُ: الْخَمْرُ حَرَامٌ، وَالْحَرَامُ شُرْبُهَا. وَالزَّوْجَةُ حَلَالٌ، وَالْحَلَالُ وَطْؤُهَا. أَوْ لِأَنَّهُ سَبَبٌ. أَوْ مُسَبَّبٌ. وَهُوَ: فَرْعُ الْحَقِيقَةِ؛ فَلِذَلِكَ تَلْزَمُهُ دُونَ الْعَكْسِ. تَنْبِيهٌ: الْحَقِيقَةُ: أَسْبَقُ إِلَى الْفَهْمِ."]]},{"id":"qa6_10","label":"مَبَاحِثُ الْأَلْفَاظِ: اللُّغَاتُ وَالْحَقِيقَةُ وَالْمَجَازُ · ١٠","segs":[["matn","وَيَصِحُّ الِاشْتِقَاقُ مِنْهُ. بِخِلَافِ الْمَجَازِ. وَمَتَى دَارَ اللَّفْظُ بَيْنَهُمَا: فَالْحَقِيقَةُ. وَلَا إِجْمَالَ؛ لِاخْتِلَالِ الْوَضْعِ بِهِ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa7","title":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ","units":[{"id":"qa7_1","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ١","segs":[["matn","فَإِنْ دَلَّ عَلَى مَعْنًى وَاحِدٍ مِنْ غَيْرِ احْتِمَالٍ لِغَيْرِهِ: فَهُوَ النَّصُّ. وَأَصْلُهُ: الظُّهُورُ وَالِارْتِفَاعُ. وَقَدْ يُطْلَقُ عَلَى الظَّاهِرِ: وَهُوَ الْمَعْنَى السَّابِقُ مِنَ اللَّفْظِ مَعَ تَجْوِيزِ غَيْرِهِ."]]},{"id":"qa7_2","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ٢","segs":[["matn","وَأَكْثَرُ مَا يُسْتَعْمَلُ بَيْنَ الْفُقَهَاءِ بِهَذَا الْمَعْنَى. فَإِنْ عَضَدَ الْغَيْرَ دَلِيلٌ بِغَلَبَةٍ: كَقَرِينَةٍ. أَوْ ظَاهِرٍ آخَرَ. أَوْ قِيَاسٍ رَاجِحٍ. سُمِّيَ: تَأْوِيلًا."]]},{"id":"qa7_3","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ٣","segs":[["matn","وَقَدْ يَكُونُ فِي الظَّاهِرِ قَرَائِنُ يَدْفَعُ الِاحْتِمَالَ مَجْمُوعُهَا دُونَ آحَادِهَا. وَالِاحْتِمَالُ: قَدْ يَبْعُدُ: فَيَحْتَاجُ إِلَى دَلِيلٍ فِي غَايَةِ الْقُوَّةِ لِدَفْعِهِ. وَقَدْ يَقْرُبُ: فَيَكْفِي أَدْنَى دَلِيلٍ. وَقَدْ يَتَوَسَّطُ: فَيَجِبُ الْمُتَوَسِّطُ."]]},{"id":"qa7_4","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ٤","segs":[["matn","فَإِنْ دَلَّ عَلَى أَحَدِ مَعْنَيَيْنِ أَوْ أَكْثَرَ لَا بِعَيْنِهِ، وَتَسَاوَتْ وَلَا قَرِينَةَ: فَمُجْمَلٌ. وَقَدْ حَدَّهُ قَوْمٌ بِمَا لَا يُفْهَمُ مِنْهُ مَعْنًى عِنْدَ الْإِطْلَاقِ."]]},{"id":"qa7_5","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ٥","segs":[["matn","فَيَكُونُ فِي الْمُشْتَرَكِ: وَهُوَ مَا تَوَحَّدَ لَفْظُهُ وَتَعَدَّدَتْ مَعَانِيهِ بِأَصْلِ الْوَضْعِ؛ كَ - الْعَيْنِ. - وَالْقَرْءِ. - وَالْمُخْتَارِ، لِلْفَاعِلِ وَالْمَفْعُولِ. - وَالْوَاوِ، لِلْعَطْفِ وَالِابْتِدَاءِ."]]},{"id":"qa7_6","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ٦","segs":[["matn","وَمِنْهُ عِنْدَ الْقَاضِي، وَبَعْضِ الْمُتَكَلِّمِينَ: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ﴾، وَ﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ﴾؛ لِتَرَدُّدِهِ بَيْنَ الْأَكْلِ وَالْبَيْعِ، وَاللَّمْسِ وَالنَّظَرِ. وَهُوَ مُخَصَّصٌ بِالْعُرْفِ فِي الْأَكْلِ وَالْوَطْءِ، فَلَيْسَ مِنْهُ."]]},{"id":"qa7_7","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ٧","segs":[["matn","وَعِنْدَ الْحَنَفِيَّةِ: مِنْهُ قَوْلُهُ: «لَا صَلَاةَ إِلَّا بِطُهُورٍ»، وَالْمُرَادُ: نَفْيُ حُكْمِهِ؛ لِامْتِنَاعِ نَفْيِ صُورَتِهِ، وَلَيْسَ حُكْمٌ أَوْلَى مِنْ حُكْمٍ. فَتَتَعَيَّنُ الصُّورَةُ الشَّرْعِيَّةُ، فَلَا يَكُونُ مِنْهُ. وَيُقَابِلُ الْمُجْمَلَ: الْمُبَيَّنُ."]]},{"id":"qa7_8","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ٨","segs":[["matn","وَهُوَ: الْمُخْرَجُ مِنْ حَيِّزِ الْإِشْكَالِ إِلَى الْوُضُوحِ. وَالْمُخْرِجُ: هُوَ الْمُبَيِّنُ. وَالْإِخْرَاجُ: هُوَ الْبَيَانُ. وَقَدْ يُسَمَّى الدَّلِيلُ: بَيَانًا. وَيَخْتَصُّ بِالْمُجْمَلِ. وَحُصُولُ الْعِلْمِ لِلْمُخَاطَبِ لَيْسَ بِشَرْطٍ. وَيَكُونُ: بِالْكَلَامِ. وَالْكِتَابَةِ. وَبِالْإِشَارَةِ. وَبِالْفِعْلِ. وَبِالتَّقْرِيرِ."]]},{"id":"qa7_9","label":"النَّصُّ وَالظَّاهِرُ وَالْمُجْمَلُ · ٩","segs":[["matn","وَبِكُلِّ مُفِيدٍ شَرْعِيٍّ. وَلَا يَجُوزُ تَأْخِيرُهُ عَنْ وَقْتِ الْحَاجَةِ. فَأَمَّا إِلَيْهَا: فَجَوَّزَهُ ابْنُ حَامِدٍ، وَالْقَاضِي وَأَصْحَابُهُ، وَبَعْضُ الْحَنَفِيَّةِ، وَأَكْثَرُ الشَّافِعِيَّةِ. وَمَنَعَهُ أَبُو بَكْرٍ عَبْدُ الْعَزِيزِ، وَالتَّمِيمِيُّ، وَالظَّاهِرِيَّةُ، وَالْمُعْتَزِلَةُ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa8","title":"الْعَامُّ","units":[{"id":"qa8_1","label":"الْعَامُّ · ١","segs":[["matn","فَإِنْ دَلَّ عَلَى مَفْهُومَاتٍ أَكْثَرَ مِنْ وَاحِدٍ مُطْلَقًا: فَعَامٌّ. وَقَدْ حَدَّهُ قَوْمٌ: بِأَنَّهُ اللَّفْظُ الْمُسْتَغْرِقُ لِمَا يَصْلُحُ لَهُ. وَهُوَ مِنْ عَوَارِضِ الْأَلْفَاظِ. فَهُوَ حَقِيقَةٌ فِيهَا، مَجَازٌ فِي غَيْرِهَا."]]},{"id":"qa8_2","label":"الْعَامُّ · ٢","segs":[["matn","وَأَصْلُهُ: الِاسْتِيعَابُ وَالِاتِّسَاعُ. وَأَلْفَاظُهُ خَمْسَةٌ: الِاسْمُ الْمُحَلَّى بِالْأَلِفِ وَاللَّامِ. وَالْمُضَافُ إِلَى مَعْرِفَةٍ؛ كَعَبْدِ زَيْدٍ. وَأَدَوَاتُ الشَّرْطِ؛ كَ «مَنْ» فِيمَنْ يَعْقِلُ. وَ«مَا» فِيمَا لَا يَعْقِلُ. وَ«أَيٍّ» فِيهِمَا. وَ«أَيْنَ»، وَ«أَيَّانَ» فِي الْمَكَانِ."]]},{"id":"qa8_3","label":"الْعَامُّ · ٣","segs":[["matn","وَ«مَتَى» فِي الزَّمَانِ. وَ«كُلٍّ». وَ«جَمِيعٍ». وَالنَّكِرَةِ فِي سِيَاقِ النَّفْيِ، كَلَا رَجُلَ فِي الدَّارِ. قَالَ الْبُسْتِيُّ: الْكَامِلُ فِي الْعُمُومِ: الْجَمْعُ؛ لِوُجُودِ صُورَتِهِ وَمَعْنَاهُ. وَالْبَاقِي قَاصِرٌ؛ لِوُجُودِهِ فِيهِ مَعْنًى لَا صُورَةً."]]},{"id":"qa8_4","label":"الْعَامُّ · ٤","segs":[["matn","وَأَنْكَرَهُ قَوْمٌ: فِيمَا فِيهِ الْأَلِفُ وَاللَّامُ. وَقَوْمٌ: فِي الْوَاحِدِ الْمُعَرَّفِ خَاصَّةً؛ كَ﴿السَّارِقُ وَالسَّارِقَةُ﴾. وَبَعْضُ مُتَأَخِّرِي النُّحَاةِ: فِي النَّكِرَةِ فِي سِيَاقِ النَّفْيِ، إِلَّا مَعَ «مِنْ» مُظْهَرَةً. وَأَقَلُّ الْجَمْعِ: ثَلَاثَةٌ."]]},{"id":"qa8_5","label":"الْعَامُّ · ٥","segs":[["matn","وَحُكِيَ عَنْ أَصْحَابِ مَالِكٍ، وَابْنِ دَاوُدَ، وَبَعْضِ النُّحَاةِ، وَالشَّافِعِيَّةِ: اثْنَانِ. وَالْمُخَاطِبُ يَدْخُلُ فِي عُمُومِ خِطَابِهِ. وَمَنَعَهُ أَبُو الْخَطَّابِ فِي الْأَمْرِ. وَقَوْمٌ: مُطْلَقًا."]]},{"id":"qa8_6","label":"الْعَامُّ · ٦","segs":[["matn","وَيَجِبُ اعْتِقَادُ عُمُومِهِ فِي الْحَالِ فِي إِحْدَى الرِّوَايَتَيْنِ، اخْتَارَهَا أَبُو بَكْرٍ، وَالْقَاضِي، وَهِيَ قَوْلُ الْحَنَفِيَّةِ. وَالْأُخْرَى: لَا، حَتَّى نَبْحَثَ فَلَا نَجِدَ مُخَصِّصًا، اخْتَارَهَا أَبُو الْخَطَّابِ. وَعَنِ الشَّافِعِيَّةِ: كَالْمَذْهَبَيْنِ."]]},{"id":"qa8_7","label":"الْعَامُّ · ٧","segs":[["matn","وَعَنِ الْحَنَفِيَّةِ: إِنِ اسْتَمَعَ مِنْهُ عَلَى وَجْهِ تَعْلِيمِ الْحُكْمِ فَكَالْأَوَّلِ، وَإِلَّا كَالثَّانِي. وَالْعَبْدُ يَدْخُلُ فِي الْخِطَابِ لِلْأُمَّةِ وَالْمُؤْمِنِينَ؛ لِأَنَّهُ مِنْهُمْ."]]},{"id":"qa8_8","label":"الْعَامُّ · ٨","segs":[["matn","وَالْإِنَاثُ فِي الْجَمْعِ بِالْوَاوِ وَالنُّونِ، وَمِثْلِ: ﴿كُلُوا وَاشْرَبُوا﴾ عِنْدَ الْقَاضِي، وَبَعْضِ الْحَنَفِيَّةِ، وَابْنِ دَاوُدَ؛ لِغَلَبَةِ الْمُذَكَّرِ. وَاخْتَارَ أَبُو الْخَطَّابِ، وَالْأَكْثَرُونَ: عَدَمَ دُخُولِهِنَّ. وَقَوْلُ الصَّحَابِيِّ: «نَهَى عَنِ الْمُزَابَنَةِ»، وَ«قَضَى بِالشُّفْعَةِ»؛ عَامٌّ."]]},{"id":"qa8_9","label":"الْعَامُّ · ٩","segs":[["matn","وَالْمُعْتَبَرُ اللَّفْظُ: فَيَعُمُّ، وَإِنِ اخْتَصَّ السَّبَبُ. وَقَالَ مَالِكٌ، وَبَعْضُ الشَّافِعِيَّةِ: يَخْتَصُّ بِسَبَبِهِ. فَإِنْ تَعَارَضَ عُمُومَانِ، وَأَمْكَنَ الْجَمْعُ بِتَقْدِيمِ الْأَخَصِّ، أَوْ تَأْوِيلِ الْمُحْتَمِلِ: فَهُوَ أَوْلَى مِنْ إِلْغَائِهِمَا."]]},{"id":"qa8_10","label":"الْعَامُّ · ١٠","segs":[["matn","وَإِلَّا: فَأَحَدُهُمَا نَاسِخٌ إِنْ عُلِمَ تَأَخُّرُهُ. وَإِلَّا: تَسَاقَطَا."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa9","title":"الْخَاصُّ وَالتَّخْصِيصُ","units":[{"id":"qa9_1","label":"الْخَاصُّ وَالتَّخْصِيصُ · ١","segs":[["matn","وَالْخَاصُّ يُقَابِلُ الْعَامَّ. وَهُوَ: مَا دَلَّ عَلَى شَيْءٍ بِعَيْنِهِ. وَلَهُمَا طَرَفَانِ وَوَاسِطَةٌ: فَعَامٌّ مُطْلَقٌ: وَهُوَ مَا لَا أَعَمَّ مِنْهُ؛ كَالْمَعْلُومِ. وَخَاصٌّ مُطْلَقٌ: وَهُوَ مَا لَا أَخَصَّ مِنْهُ؛ كَزَيْدٍ."]]},{"id":"qa9_2","label":"الْخَاصُّ وَالتَّخْصِيصُ · ٢","segs":[["matn","وَمَا بَيْنَهُمَا: فَعَامٌّ بِالنِّسْبَةِ إِلَى مَا تَحْتَهُ، خَاصٌّ بِالنِّسْبَةِ إِلَى مَا فَوْقَهُ؛ كَالْمَوْجُودِ. وَالتَّخْصِيصُ: إِخْرَاجُ بَعْضِ مَا تَنَاوَلَهُ اللَّفْظُ. فَيُفَارِقُ النَّسْخَ: بِأَنَّهُ رَفْعٌ لِجَمِيعِهِ. وَبِجَوَازِ مُقَارَنَةِ الْمُخَصِّصِ. وَعَدَمِ وُجُوبِ مُقَاوَمَتِهِ."]]},{"id":"qa9_3","label":"الْخَاصُّ وَالتَّخْصِيصُ · ٣","segs":[["matn","وَدُخُولِهِ عَلَى الْخَبَرِ. بِخِلَافِ النَّسْخِ. وَلَا خِلَافَ فِي جَوَازِ التَّخْصِيصِ. وَالْمُخَصِّصَاتُ تِسْعَةٌ: الْحِسُّ: كَخُرُوجِ السَّمَاءِ وَالْأَرْضِ مِنْ: ﴿تُدَمِّرُ كُلَّ شَيْءٍ﴾. وَالْعَقْلُ: وَبِهِ خَرَجَ مَنْ لَا يَفْهَمُ مِنَ التَّكَالِيفَ. وَالْإِجْمَاعُ."]]},{"id":"qa9_4","label":"الْخَاصُّ وَالتَّخْصِيصُ · ٤","segs":[["matn","وَالْحَقُّ: أَنَّهُ لَيْسَ بِمُخَصِّصٍ، بَلْ دَالٌّ عَلَى وُجُودِهِ. وَالنَّصُّ الْخَاصُّ: كَ«لَا قَطْعَ إِلَّا فِي رُبُعِ دِينَارٍ». وَلَا يُشْتَرَطُ تَأَخُّرُهُ."]]},{"id":"qa9_5","label":"الْخَاصُّ وَالتَّخْصِيصُ · ٥","segs":[["matn","وَعَنْهُ: بَلَى، فَيُقَدَّمُ الْمُتَأَخِّرُ وَإِنْ كَانَ عَامًّا، كَقَوْلِ الْحَنَفِيَّةِ، فَيَكُونُ نَسْخًا لِلْخَاصِّ كَمَا لَوْ أَفْرَدَهُ. فَعَلَى هَذَا: مَتَى جُهِلَ الْمُتَقَدِّمُ تَعَارَضَا؛ لِاحْتِمَالِ النَّسْخِ بِتَأَخُّرِ الْعَامِّ، وَاحْتِمَالِ التَّخْصِيصِ بِتَقَدُّمِهِ."]]},{"id":"qa9_6","label":"الْخَاصُّ وَالتَّخْصِيصُ · ٦","segs":[["matn","وَقَالَ بَعْضُ الْحَنَفِيَّةِ: الْكِتَابُ لَا يُخَصِّصُ السُّنَّةَ. وَخَرَّجَهُ ابْنُ حَامِدٍ رِوَايَةً لَنَا. وَالْمَفْهُومُ: كَخُرُوجِ الْمَعْلُوفَةِ بِقَوْلِهِ: «فِي سَائِمَةِ الْغَنَمِ زَكَاةٌ» مِنْ قَوْلِهِ: «فِي أَرْبَعِينَ شَاةً: شَاةٌ»."]]},{"id":"qa9_7","label":"الْخَاصُّ وَالتَّخْصِيصُ · ٧","segs":[["matn","وَفِعْلُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَتَقْرِيرُهُ. وَقَوْلُ الصَّحَابِيِّ، إِنْ كَانَ حُجَّةً. وَقِيَاسُ نَصٍّ خَاصٍّ فِي قَوْلِ أَبِي بَكْرٍ، وَالْقَاضِي، وَجَمَاعَةٍ مِنَ الْفُقَهَاءِ وَالْمُتَكَلِّمِينَ."]]},{"id":"qa9_8","label":"الْخَاصُّ وَالتَّخْصِيصُ · ٨","segs":[["matn","وَقَالَ ابْنُ شَاقْلَا، وَجَمَاعَةٌ مِنَ الْفُقَهَاءِ: لَا يُخَصُّ. وَقَالَ قَوْمٌ: بِالْجَلِيِّ دُونَ الْخَفِيِّ. وَخَصَّصَ بِهِ عِيسَى بْنُ أَبَانَ الْعَامَّ الْمَخْصُوصَ، وَحُكِيَ عَنْ أَبِي حَنِيفَةَ. وَيَجُوزُ تَخْصِيصُ الْعُمُومِ إِلَى الْوَاحِدِ."]]},{"id":"qa9_9","label":"الْخَاصُّ وَالتَّخْصِيصُ · ٩","segs":[["matn","وَقَالَ الرَّازِيُّ، وَالْقَفَّالُ، وَالْغَزَّالِيُّ: إِلَى أَقَلِّ الْجَمْعِ. وَهُوَ حُجَّةٌ فِي الْبَاقِي عِنْدَ الْجُمْهُورِ. خِلَافًا لِأَبِي ثَوْرٍ وَعِيسَى بْنِ أَبَانَ."]]},{"id":"qa9_10","label":"الْخَاصُّ وَالتَّخْصِيصُ · ١٠","segs":[["matn","وَمِنْهُ: الِاسْتِثْنَاءُ: وَهُوَ قَوْلٌ مُتَّصِلٌ يَدُلُّ عَلَى أَنَّ الْمَذْكُورَ مَعَهُ غَيْرُ مُرَادٍ بِالْقَوْلِ الْأَوَّلِ. فَيُفَارِقُ التَّخْصِيصَ: بِالِاتِّصَالِ. وَتَطَرُّقِهِ إِلَى النَّصِّ؛ كَعَشَرَةٍ إِلَّا ثَلَاثَةً. وَيُفَارِقُ النَّسْخَ: بِالِاتِّصَالِ."]]},{"id":"qa9_11","label":"الْخَاصُّ وَالتَّخْصِيصُ · ١١","segs":[["matn","وَبِأَنَّهُ مَانِعٌ لِدُخُولِ مَا جَازَ دُخُولُهُ، وَالنَّسْخُ رَافِعٌ لِمَا دَخَلَ. وَبِأَنَّهُ رَفْعٌ لِلْبَعْضِ، وَالنَّسْخُ رَفْعٌ لِلْجَمِيعِ. وَشَرْطُهُ: الِاتِّصَالُ: فَلَا يَفْصِلُ بَيْنَهُمَا سُكُوتٌ يُمْكِنُ الْكَلَامُ فِيهِ."]]},{"id":"qa9_12","label":"الْخَاصُّ وَالتَّخْصِيصُ · ١٢","segs":[["matn","وَحُكِيَ عَنِ ابْنِ عَبَّاسٍ: عَدَمُ اشْتِرَاطِهِ. وَعَنْ عَطَاءٍ، وَالْحَسَنِ: تَعْلِيقُهُ بِالْمَجْلِسِ، وَقَدْ أَوْمَأَ إِلَيْهِ أَحْمَدُ فِي الْيَمِينِ. وَأَنْ يَكُونَ مِنَ الْجِنْسِ، وَبِهِ قَالَ بَعْضُ الشَّافِعِيَّةِ."]]},{"id":"qa9_13","label":"الْخَاصُّ وَالتَّخْصِيصُ · ١٣","segs":[["matn","وَقَالَ مَالِكٌ، وَأَبُو حَنِيفَةَ، وَبَعْضُ الْمُتَكَلِّمِينَ: لَيْسَ بِشَرْطٍ. وَأَنْ يَكُونَ الْمُسْتَثْنَى أَقَلَّ مِنَ النِّصْفِ. وَفِي النِّصْفِ: وَجْهَانِ. وَأَجَازَ الْأَكْثَرُونَ: الْأَكْثَرَ. فَإِنْ تَعَقَّبَ جُمَلًا: عَادَ إِلَى جَمِيعِهَا. وَقَالَ الْحَنَفِيَّةُ: إِلَى الْأَقْرَبِ. وَهُوَ: مِنَ الْإِثْبَاتِ: نَفْيٌ. وَمِنَ النَّفْيِ: إِثْبَاتٌ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa10","title":"الْمُطْلَقُ وَالْمُقَيَّدُ","units":[{"id":"qa10_1","label":"الْمُطْلَقُ وَالْمُقَيَّدُ · ١","segs":[["matn","وَمِنْهُ: الْمُطْلَقُ، وَهُوَ: مَا تَنَاوَلَ وَاحِدًا لَا بِعَيْنِهِ بِاعْتِبَارِ حَقِيقَةٍ شَامِلَةٍ لِجِنْسِهِ. وَقِيلَ: لَفْظٌ يَدُلُّ عَلَى مَعْنًى مُبْهَمٍ فِي جِنْسِهِ."]]},{"id":"qa10_2","label":"الْمُطْلَقُ وَالْمُقَيَّدُ · ٢","segs":[["matn","وَيُقَابِلُهُ: الْمُقَيَّدُ، وَهُوَ: الْمُتَنَاوِلُ لِمَوْصُوفٍ بِأَمْرٍ زَائِدٍ عَلَى الْحَقِيقَةِ الشَّامِلَةِ لِجِنْسِهِ؛ كَ﴿رَقَبَةٍ مُؤْمِنَةٍ﴾."]]},{"id":"qa10_3","label":"الْمُطْلَقُ وَالْمُقَيَّدُ · ٣","segs":[["matn","فَإِنْ وَرَدَ مُطْلَقٌ وَمُقَيَّدٌ: فَإِنِ اتَّحَدَ الْحُكْمُ وَالسَّبَبُ؛ كَ«لَا نِكَاحَ إِلَّا بِوَلِيٍّ» مَعَ: «لَا نِكَاحَ إِلَّا بِوَلِيٍّ مُرْشِدٍ»: حُمِلَ الْمُطْلَقُ عَلَى الْمُقَيَّدِ. وَقَالَ أَبُو حَنِيفَةَ: زِيَادَةٌ، فَهِيَ نَسْخٌ."]]},{"id":"qa10_4","label":"الْمُطْلَقُ وَالْمُقَيَّدُ · ٤","segs":[["matn","وَإِنِ اخْتَلَفَ السَّبَبُ؛ كَالْعِتْقِ فِي كَفَّارَةِ الْيَمِينِ، قُيِّدَ بِالْإِيمَانِ وَأُطْلِقَ فِي الظِّهَارِ: فَالْمَنْصُوصُ لَا يُحْمَلُ، وَاخْتَارَهُ ابْنُ شَاقْلَا، وَهُوَ قَوْلُ أَكْثَرِ الْحَنَفِيَّةِ. خِلَافًا لِلْقَاضِي، وَالْمَالِكِيَّةِ، وَبَعْضِ الشَّافِعِيَّةِ."]]},{"id":"qa10_5","label":"الْمُطْلَقُ وَالْمُقَيَّدُ · ٥","segs":[["matn","وَقَالَ أَبُو الْخَطَّابِ: تَقْيِيدُ الْمُطْلَقِ كَتَخْصِيصِ الْعُمُومِ، وَهُوَ جَائِزٌ بِالْقِيَاسِ الْخَاصِّ، فَهَا هُنَا مِثْلُهُ. فَإِنْ كَانَ ثَمَّ مُقَيَّدَانِ؛ حُمِلَ عَلَى أَقْرَبِهِمَا شِبْهًا بِهِ."]]},{"id":"qa10_6","label":"الْمُطْلَقُ وَالْمُقَيَّدُ · ٦","segs":[["matn","وَإِنِ اخْتَلَفَ الْحُكْمُ: فَلَا حَمْلَ، اتَّحَدَ السَّبَبُ أَوِ اخْتَلَفَ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa11","title":"الْأَمْرُ","units":[{"id":"qa11_1","label":"الْأَمْرُ · ١","segs":[["matn","وَالْأَمْرُ: اسْتِدْعَاءُ الْفِعْلِ بِالْقَوْلِ عَلَى وَجْهِ الِاسْتِعْلَاءِ. وَلَهُ صِيغَةٌ تَدُلُّ بِمُجَرَّدِهَا عَلَيْهِ، وَهِيَ: افْعَلْ: لِلْحَاضِرِ. وَلْيَفْعَلْ: لِلْغَائِبِ. عِنْدَ الْجُمْهُورِ. وَمَنْ تَخَيَّلَ الْكَلَامَ مَعْنًى قَائِمًا بِالنَّفْسِ؛ أَنْكَرَ الصِّيغَةَ. وَلَيْسَ بِشَيْءٍ."]]},{"id":"qa11_2","label":"الْأَمْرُ · ٢","segs":[["matn","وَالْإِرَادَةُ لَيْسَتْ شَرْطًا عِنْدَ الْأَكْثَرِينَ. خِلَافًا لِلْمُعْتَزِلَةِ. وَهُوَ لِلْوُجُوبِ بِتَجَرُّدِهِ عِنْدَ الْفُقَهَاءِ وَبَعْضِ الْمُتَكَلِّمِينَ. وَقَالَ بَعْضُهُمْ: لِلْإِبَاحَةِ. وَبَعْضُ الْمُعْتَزِلَةِ: لِلنَّدْبِ. فَإِنْ وَرَدَ بَعْدَ الْحَظْرِ: فَلِلْإِبَاحَةِ."]]},{"id":"qa11_3","label":"الْأَمْرُ · ٣","segs":[["matn","وَقَالَ أَكْثَرُ الْفُقَهَاءِ وَالْمُتَكَلِّمِينَ: لِمَا يُفِيدُهُ قَبْلَ الْحَظْرِ. وَلَا يَقْتَضِي التَّكْرَارَ عِنْدَ الْأَكْثَرِينَ، وَأَبِي الْخَطَّابِ. خِلَافًا لِلْقَاضِي، وَبَعْضِ الشَّافِعِيَّةِ. وَقِيلَ: يَتَكَرَّرُ إِنْ عُلِّقَ عَلَى شَرْطٍ."]]},{"id":"qa11_4","label":"الْأَمْرُ · ٤","segs":[["matn","وَقِيلَ: يَتَكَرَّرُ بِتَكَرُّرِ لَفْظِ الْأَمْرِ، وَحُكِيَ ذَلِكَ عَنْ أَبِي حَنِيفَةَ وَأَصْحَابِهِ. وَهُوَ عَلَى الْفَوْرِ فِي ظَاهِرِ الْمَذْهَبِ، كَالْحَنَفِيَّةِ. وَقَالَ أَكْثَرُ الشَّافِعِيَّةِ: عَلَى التَّرَاخِي. وَقَوْمٌ: بِالْوَقْفِ."]]},{"id":"qa11_5","label":"الْأَمْرُ · ٥","segs":[["matn","وَالْمُؤَقَّتُ: لَا يَسْقُطُ بِفَوْتِ وَقْتِهِ، فَيَجِبُ قَضَاؤُهُ. وَقَالَ أَبُو الْخَطَّابِ، وَالْأَكْثَرُونَ: بِأَمْرٍ جَدِيدٍ. وَيَقْتَضِي الْإِجْزَاءَ بِفِعْلِ الْمَأْمُورِ بِهِ عَلَى وَجْهِهِ. وَقِيلَ: لَا يَقْتَضِيهِ. وَلَا يَمْنَعُ وُجُوبَ الْقَضَاءِ إِلَّا بِدَلِيلٍ مُنْفَصِلٍ."]]},{"id":"qa11_6","label":"الْأَمْرُ · ٦","segs":[["matn","وَالْأَمْرُ: لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَفْظٍ لَا تَخْصِيصَ فِيهِ لَهُ: يُشَارِكُهُ فِيهِ غَيْرُهُ. وَكَذَلِكَ خِطَابُهُ لِوَاحِدٍ مِنَ الصَّحَابَةِ. وَلَا يَخْتَصُّ إِلَّا بِدَلِيلٍ، وَهَذَا قَوْلُ الْقَاضِي وَبَعْضِ الْمَالِكِيَّةِ وَالشَّافِعِيَّةِ."]]},{"id":"qa11_7","label":"الْأَمْرُ · ٧","segs":[["matn","وَقَالَ التَّمِيمِيُّ، وَأَبُو الْخَطَّابِ، وَبَعْضُ الشَّافِعِيَّةِ: يَخْتَصُّ بِالْمَأْمُورِ. وَيَتَعَلَّقُ بِالْمَعْدُومِ. خِلَافًا لِلْمُعْتَزِلَةِ وَجَمَاعَةٍ مِنَ الْحَنَفِيَّةِ. وَيَجُوزُ أَمْرُ الْمُكَلَّفِ بِمَا عُلِمَ أَنَّهُ لَا يَتَمَكَّنُ مِنْ فِعْلِهِ."]]},{"id":"qa11_8","label":"الْأَمْرُ · ٨","segs":[["matn","وَهِيَ مَبْنِيَّةٌ عَلَى النَّسْخِ قَبْلَ التَّمَكُّنِ. وَالْمُعْتَزِلَةُ: شَرَطُوا تَعْلِيقَهُ بِشَرْطِ أَلَّا يَعْلَمَ الْآمِرُ عَدَمَهُ. وَهُوَ نَهْيٌ عَنْ ضِدِّهِ مَعْنًى."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa12","title":"النَّهْيُ","units":[{"id":"qa12_1","label":"النَّهْيُ · ١","segs":[["matn","وَالنَّهْيُ يُقَابِلُ الْأَمْرَ عَكْسًا: وَهُوَ اسْتِدْعَاءُ التَّرْكِ بِالْقَوْلِ عَلَى وَجْهِ الِاسْتِعْلَاءِ. وَلِكُلِّ مَسْأَلَةٍ مِنَ الْأَوَامِرِ وِزَانٌ مِنَ النَّوَاهِي بِعَكْسِهَا، وَقَدِ اتَّضَحَ كَثِيرٌ مِنْ أَحْكَامِهِ."]]},{"id":"qa12_2","label":"النَّهْيُ · ٢","segs":[["matn","بَقِيَ: أَنَّ النَّهْيَ عَنِ الْأَسْبَابِ الْمُفِيدَةِ لِلْأَحْكَامِ: يَقْتَضِي فَسَادَهَا. وَقِيلَ: لِعَيْنِهِ لَا لِغَيْرِهِ. وَقِيلَ: فِي الْعِبَادَاتِ لَا فِي الْمُعَامَلَاتِ. وَحُكِيَ عَنْ جَمَاعَةٍ، مِنْهُمْ أَبُو حَنِيفَةَ: يَقْتَضِي الصِّحَّةَ."]]},{"id":"qa12_3","label":"النَّهْيُ · ٣","segs":[["matn","وَقَالَ بَعْضُ الْفُقَهَاءِ، وَعَامَّةُ الْمُتَكَلِّمِينَ: لَا يَقْتَضِي فَسَادًا وَلَا صِحَّةً. فَهَذَا مَا تَقْتَضِيهِ صَرَائِحُ الْأَلْفَاظِ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa13","title":"الْمَفْهُومُ","units":[{"id":"qa13_1","label":"الْمَفْهُومُ · ١","segs":[["matn","وَأَمَّا الْمُسْتَفَادُ مِنْ فَحْوَى الْأَلْفَاظِ وَإِشَارَاتِهَا، وَهُوَ: الْمَفْهُومُ، فَأَرْبَعَةُ أَضْرُبٍ: الْأَوَّلُ: الِاقْتِضَاءُ: وَهُوَ الْإِضْمَارُ الضَّرُورِيُّ: لِصِدْقِ الْمُتَكَلِّمِ، مِثْلُ: «صَحِيحًا» فِي قَوْلِهِ: «لَا عَمَلَ إِلَّا بِنِيَّةٍ»."]]},{"id":"qa13_2","label":"الْمَفْهُومُ · ٢","segs":[["matn","أَوْ لِيُوجَدَ الْمَلْفُوظُ بِهِ شَرْعًا، مِثْلُ: «فَأَفْطَرَ»، لِقَوْلِهِ: ﴿فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ﴾. أَوْ عَقْلًا، مِثْلُ: «الْوَطْءِ» فِي مِثْلِ: ﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ﴾."]]},{"id":"qa13_3","label":"الْمَفْهُومُ · ٣","segs":[["matn","الثَّانِي: الْإِيمَاءُ، وَالْإِشَارَةُ، وَفَحْوَى الْكَلَامِ، وَلَحْنُهُ: كَفَهْمِ عِلِّيَّةِ السَّرِقَةِ فِي قَوْلِهِ تَعَالَى: ﴿وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا أَيْدِيَهُمَا﴾."]]},{"id":"qa13_4","label":"الْمَفْهُومُ · ٤","segs":[["matn","الثَّالِثُ: التَّنْبِيهُ، وَهُوَ مَفْهُومُ الْمُوَافَقَةِ: بِأَنْ يُفْهَمَ الْحُكْمُ فِي الْمَسْكُوتِ مِنَ الْمَنْطُوقِ بِسِيَاقِ الْكَلَامِ؛ كَتَحْرِيمِ الضَّرْبِ مِنْ قَوْلِهِ: ﴿وَلَا تَقُلْ لَهُمَا أُفٍّ﴾. قَالَ الْخَرَزِيُّ، وَبَعْضُ الشَّافِعِيَّةِ: هُوَ قِيَاسٌ."]]},{"id":"qa13_5","label":"الْمَفْهُومُ · ٥","segs":[["matn","وَقَالَ الْقَاضِي، وَبَعْضُ الشَّافِعِيَّةِ: بَلْ مِنْ مَفْهُومِ اللَّفْظِ، سَبَقَ إِلَى الْفَهْمِ مُقَارِنًا. وَهُوَ قَاطِعٌ عَلَى الْقَوْلَيْنِ."]]},{"id":"qa13_6","label":"الْمَفْهُومُ · ٦","segs":[["matn","الرَّابِعُ: دَلِيلُ الْخِطَابِ، وَهُوَ مَفْهُومُ الْمُخَالَفَةِ؛ كَدَلَالَةِ تَخْصِيصِ الشَّيْءِ بِالذِّكْرِ عَلَى نَفْيِهِ عَمَّا عَدَاهُ؛ كَخُرُوجِ الْمَعْلُوفَةِ بِقَوْلِهِ: «فِي سَائِمَةِ الْغَنَمِ زَكَاةٌ». وَهُوَ حُجَّةٌ عِنْدَ الْأَكْثَرِينَ، خِلَافًا لِأَبِي حَنِيفَةَ وَبَعْضِ الْمُتَكَلِّمِينَ."]]},{"id":"qa13_7","label":"الْمَفْهُومُ · ٧","segs":[["matn","وَدَرَجَاتُهُ سِتٌّ: إِحْدَاهَا: مَفْهُومُ الْغَايَةِ بِ«إِلَى»، أَوْ «حَتَّى»؛ مِثْلُ: ﴿أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ﴾. أَنْكَرَهُ بَعْضُ مُنْكِرِي الْمَفْهُومِ. الثَّانِيَةُ: مَفْهُومُ الشَّرْطِ؛ مِثْلُ: ﴿وَإِنْ كُنَّ أُولَاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ﴾. أَنْكَرَهُ قَوْمٌ."]]},{"id":"qa13_8","label":"الْمَفْهُومُ · ٨","segs":[["matn","الثَّالِثَةُ: مَفْهُومُ التَّخْصِيصِ: وَهُوَ أَنْ تُذْكَرَ الصِّفَةُ عَقِيبَ الِاسْمِ الْعَامِّ فِي مَعْرِضِ الْإِثْبَاتِ وَالْبَيَانِ؛ كَقَوْلِهِ: «فِي سَائِمَةِ الْغَنَمِ الزَّكَاةُ». وَهُوَ حُجَّةٌ."]]},{"id":"qa13_9","label":"الْمَفْهُومُ · ٩","segs":[["matn","وَمِثْلُهُ: أَنْ يَثْبُتَ الْحُكْمُ فِي أَحَدٍ فَيَنْتَفِيَ فِي الْآخَرِ؛ مِثْلُ: «الْأَيِّمُ أَحَقُّ بِنَفْسِهَا»."]]},{"id":"qa13_10","label":"الْمَفْهُومُ · ١٠","segs":[["matn","الرَّابِعَةُ: مَفْهُومُ الصِّفَةِ: وَهُوَ تَخْصِيصُهُ بِبَعْضِ الْأَوْصَافِ الَّتِي تَطْرَأُ وَتَزُولُ؛ مِثْلُ: «الثَّيِّبُ أَحَقُّ بِنَفْسِهَا»، وَبِهِ قَالَ جُلُّ أَصْحَابِ الشَّافِعِيِّ. وَاخْتَارَ التَّمِيمِيُّ: أَنَّهُ لَيْسَ بِحُجَّةٍ، وَهُوَ قَوْلُ أَكْثَرِ الْفُقَهَاءِ وَالْمُتَكَلِّمِينَ."]]},{"id":"qa13_11","label":"الْمَفْهُومُ · ١١","segs":[["matn","الْخَامِسَةُ: مَفْهُومُ الْعَدَدِ: وَهُوَ تَخْصِيصُهُ بِنَوْعٍ مِنَ الْعَدَدِ؛ مِثْلَ: «لَا تُحَرِّمُ الْمَصَّةُ وَالْمَصَّتَانِ»، وَبِهِ قَالَ مَالِكٌ، وَدَاوُدُ، وَبَعْضُ الشَّافِعِيَّةِ. خِلَافًا لِأَبِي حَنِيفَةَ، وَجُلِّ أَصْحَابِ الشَّافِعِيِّ."]]},{"id":"qa13_12","label":"الْمَفْهُومُ · ١٢","segs":[["matn","السَّادِسَةُ: مَفْهُومُ اللَّقَبِ: وَهُوَ أَنْ يَخُصَّ اسْمًا بِحُكْمٍ. وَأَنْكَرَهُ الْأَكْثَرُونَ، وَهُوَ الصَّحِيحُ؛ لِمَنْعِ جَرَيَانِ الرِّبَا فِي غَيْرِ الْأَنْوَاعِ السِّتَّةِ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa14","title":"النَّسْخُ","units":[{"id":"qa14_1","label":"النَّسْخُ · ١","segs":[["matn","ثُمَّ الَّذِي يَرْفَعُ الْحُكْمَ بَعْدَ ثُبُوتِهِ: النَّسْخُ. وَأَصْلُهُ: الْإِزَالَةُ. وَهُوَ: رَفْعُ الْحُكْمِ الثَّابِتِ بِخِطَابٍ مُتَقَدِّمٍ، بِخِطَابٍ مُتَرَاخٍ عَنْهُ."]]},{"id":"qa14_2","label":"النَّسْخُ · ٢","segs":[["matn","وَ«الرَّفْعُ»: إِزَالَةُ الشَّيْءِ عَلَى وَجْهٍ لَوْلَاهُ لَبَقِيَ ثَابِتًا؛ لِيَخْرُجَ زَوَالُ الْحُكْمِ بِخُرُوجِ وَقْتِهِ. وَ (الثَّابِتُ بِخِطَابٍ مُتَقَدِّمٍ): لِيَخْرُجَ الثَّابِتُ بِالْأَصَالَةِ. وَ«بِخِطَابٍ مُتَأَخِّرٍ»: لِيَخْرُجَ زَوَالُهُ بِزَوَالِ التَّكْلِيفِ. وَ«مُتَرَاخٍ عَنْهُ»: لِيَخْرُجَ الْبَيَانُ."]]},{"id":"qa14_3","label":"النَّسْخُ · ٣","segs":[["matn","وَقِيلَ: هُوَ كَشْفُ مُدَّةِ الْعِبَادَةِ بِخِطَابٍ ثَانٍ. وَالْمُعْتَزِلَةُ قَالُوا: الْخِطَابُ الدَّالُّ عَلَى أَنَّ مِثْلَ الْحُكْمِ الثَّابِتِ بِالنَّصِّ زَائِلٌ عَلَى وَجْهٍ لَوْلَاهُ لَكَانَ ثَابِتًا."]]},{"id":"qa14_4","label":"النَّسْخُ · ٤","segs":[["matn","وَهُوَ خَالٍ مِنَ الرَّفْعِ الَّذِي هُوَ حَقِيقَةُ النَّسْخِ. وَيَجُوزُ قَبْلَ التَّمَكُّنِ مِنَ الِامْتِثَالِ. وَالزِّيَادَةُ عَلَى النَّصِّ: إِنْ لَمْ تَتَعَلَّقْ بِالْمَزِيدِ؛ كَإِيجَابِ الصَّلَاةِ ثُمَّ الصَّوْمِ: فَلَيْسَ بِنَسْخٍ إِجْمَاعًا."]]},{"id":"qa14_5","label":"النَّسْخُ · ٥","segs":[["matn","وَإِنْ تَعَلَّقَتْ: - وَلَيْسَتْ بِشَرْطٍ: فَنَسْخٌ عِنْدَ أَبِي حَنِيفَةَ. - فَإِنْ كَانَتْ شَرْطًا؛ كَالنِّيَّةِ فِي الطَّهَارَةِ: فَأَبُو حَنِيفَةَ وَبَعْضُ مُخَالِفِيهِ فِي الْأُولَى نَسْخٌ. وَيَجُوزُ: إِلَى غَيْرِ بَدَلٍ. وَقِيلَ: لَا."]]},{"id":"qa14_6","label":"النَّسْخُ · ٦","segs":[["matn","وَبِالْأَخَفِّ وَالْأَثْقَلِ. وَقِيلَ: بِالْأَخَفِّ. وَلَا نَسْخَ قَبْلَ بُلُوغِ النَّاسِخِ. وَقَالَ أَبُو الْخَطَّابِ: كَعَزْلِ الْوَكِيلِ قَبْلَ عِلْمِهِ بِهِ. وَيَجُوزُ نَسْخُ: الْقُرْآنِ وَالسُّنَّةِ الْمُتَوَاتِرَةِ وَالْآحَادِ: بِمِثْلِهَا. وَالسُّنَّةِ: بِالْقُرْآنِ."]]},{"id":"qa14_7","label":"النَّسْخُ · ٧","segs":[["matn","لَا هُوَ بِهَا فِي ظَاهِرِ كَلَامِهِ. خِلَافًا لِأَبِي الْخَطَّابِ وَبَعْضِ الشَّافِعِيَّةِ. فَأَمَّا نَسْخُ الْقُرْآنِ وَمُتَوَاتِرِ السُّنَّةِ بِالْآحَادِ: فَجَائِزٌ عَقْلًا. مُمْتَنِعٌ شَرْعًا. إِلَّا عِنْدَ بَعْضِ الظَّاهِرِيَّةِ."]]},{"id":"qa14_8","label":"النَّسْخُ · ٨","segs":[["matn","وَقِيلَ: يَجُوزُ فِي زَمَنِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَمَا ثَبَتَ بِالْقِيَاسِ: إِنْ كَانَ مَنْصُوصًا عَلَى عِلَّتِهِ: فَكَالنَّصِّ يُنْسَخُ وَيُنْسَخُ بِهِ، وَإِلَّا فَلَا. وَقِيلَ: يَجُوزُ بِمَا جَازَ بِهِ التَّخْصِيصُ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa15","title":"الْأَصْلُ الثَّالِثُ: الْإِجْمَاعُ","units":[{"id":"qa15_1","label":"الْأَصْلُ الثَّالِثُ: الْإِجْمَاعُ · ١","segs":[["matn","وَالْإِجْمَاعُ: وَأَصْلُهُ الِاتِّفَاقُ، وَهُوَ: اتِّفَاقُ عُلَمَاءِ الْعَصْرِ مِنَ الْأُمَّةِ عَلَى أَمْرٍ دِينِيٍّ. وَقِيلَ: اتِّفَاقُ أَهْلِ الْحَلِّ وَالْعَقْدِ عَلَى حُكْمِ الْحَادِثَةِ قَوْلًا. وَإِجْمَاعُ أَهْلِ كُلِّ عَصْرٍ حُجَّةٌ."]]},{"id":"qa15_2","label":"الْأَصْلُ الثَّالِثُ: الْإِجْمَاعُ · ٢","segs":[["matn","خِلَافًا لِدَاوُدَ، وَقَدْ أَوْمَأَ أَحْمَدُ إِلَى نَحْوِ قَوْلِهِ. وَإِجْمَاعُ التَّابِعِينَ عَلَى أَحَدِ قَوْلَيِ الصَّحَابَةِ: اعْتَبَرَهُ أَبُو الْخَطَّابِ، وَالْحَنَفِيَّةُ. وَقَالَ الْقَاضِي، وَبَعْضُ الشَّافِعِيَّةِ: لَيْسَ بِإِجْمَاعٍ."]]},{"id":"qa15_3","label":"الْأَصْلُ الثَّالِثُ: الْإِجْمَاعُ · ٣","segs":[["matn","وَالتَّابِعِيُّ مُعْتَبَرٌ فِي عَصْرِ الصَّحَابَةِ عِنْدَ الْجُمْهُورِ. خِلَافًا لِلْقَاضِي، وَبَعْضِ الشَّافِعِيَّةِ. وَقَدْ أَوْمَأَ أَحْمَدُ إِلَى الْقَوْلَيْنِ. وَلَا يَنْعَقِدُ بِقَوْلِ الْأَكْثَرِينَ. خِلَافًا لِابْنِ جَرِيرٍ، وَأَوْمَأَ إِلَيْهِ أَحْمَدُ."]]},{"id":"qa15_4","label":"الْأَصْلُ الثَّالِثُ: الْإِجْمَاعُ · ٤","segs":[["matn","وَقَالَ مَالِكٌ: إِجْمَاعُ أَهْلِ الْمَدِينَةِ حُجَّةٌ. وَانْقِرَاضُ الْعَصْرِ شَرْطٌ فِي ظَاهِرِ كَلَامِهِ. وَقَدْ أَوْمَأَ إِلَى خِلَافِهِ. فَلَوِ اتَّفَقَتِ الْكَلِمَةُ فِي لَحْظَةٍ وَاحِدَةٍ فَهُوَ إِجْمَاعٌ عِنْدَ الْجُمْهُورِ، وَاخْتَارَهُ أَبُو الْخَطَّابِ."]]},{"id":"qa15_5","label":"الْأَصْلُ الثَّالِثُ: الْإِجْمَاعُ · ٥","segs":[["matn","وَإِذَا اخْتَلَفَ الصَّحَابَةُ عَلَى قَوْلَيْنِ: لَمْ يَجُزْ إِحْدَاثُ قَوْلٍ ثَالِثٍ عِنْدَ الْجُمْهُورِ. وَقَالَ بَعْضُ الْحَنَفِيَّةِ وَالظَّاهِرِيَّةِ: يَجُوزُ. وَإِذَا قَالَ بَعْضُ الْمُجْتَهِدِينَ قَوْلًا، وَانْتَشَرَ فِي الْبَاقِينَ، وَسَكَتُوا: فَعَنْهُ: إِجْمَاعٌ فِي التَّكَالِيفِ."]]},{"id":"qa15_6","label":"الْأَصْلُ الثَّالِثُ: الْإِجْمَاعُ · ٦","segs":[["matn","وَبِهِ قَالَ بَعْضُ الشَّافِعِيَّةِ. وَقِيلَ: حُجَّةٌ لَا إِجْمَاعٌ. وَقِيلَ: لَا إِجْمَاعٌ، وَلَا حُجَّةٌ. وَيَجُوزُ أَنْ يَنْعَقِدَ عَنِ اجْتِهَادٍ. وَأَحَالَهُ قَوْمٌ. وَقِيلَ: يُتَصَوَّرُ، وَلَيْسَ بِحُجَّةٍ."]]},{"id":"qa15_7","label":"الْأَصْلُ الثَّالِثُ: الْإِجْمَاعُ · ٧","segs":[["matn","وَالْأَخْذُ بِأَقَلِّ مَا قِيلَ لَيْسَ تَمَسُّكًا بِالْإِجْمَاعِ. وَاتِّفَاقُ الْخُلَفَاءِ الْأَرْبَعَةِ لَيْسَ بِإِجْمَاعٍ. وَقَدْ نُقِلَ عَنْهُ: لَا نَخْرُجُ عَنْ قَوْلِهِمْ إِلَى قَوْلِ غَيْرِهِمْ. وَهَذَا يَدُلُّ عَلَى أَنَّهُ حُجَّةٌ لَا إِجْمَاعٌ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa16","title":"الْأَصْلُ الرَّابِعُ: الِاسْتِصْحَابُ","units":[{"id":"qa16_1","label":"الْأَصْلُ الرَّابِعُ: الِاسْتِصْحَابُ · ١","segs":[["matn","وَأَمَّا الْأَصْلُ الرَّابِعُ: وَهُوَ دَلِيلُ الْعَقْلِ فِي النَّفْيِ الْأَصْلِيِّ. فَهُوَ: أَنَّ الذِّمَّةَ قَبْلَ الشَّرْعِ بَرِيئَةٌ مِنَ التَّكَالِيفِ، فَيَسْتَمِرُّ حَتَّى يَرِدَ غَيْرُهُ. وَيُسَمَّى: اسْتِصْحَابًا. وَكُلُّ دَلِيلٍ فَهُوَ كَذَلِكَ."]]},{"id":"qa16_2","label":"الْأَصْلُ الرَّابِعُ: الِاسْتِصْحَابُ · ٢","segs":[["matn","فَالنَّصُّ: حَتَّى يَرِدَ النَّاسِخُ. وَالْعُمُومُ: حَتَّى يَرِدَ الْمُخَصِّصُ. وَالْمِلْكُ: حَتَّى يَرِدَ الْمُزِيلُ. وَالنَّفْيُ: حَتَّى يَرِدَ الْمُثْبِتُ. وَوُجُوبُ صَلَاةٍ سَادِسَةٍ، وَصَوْمِ غَيْرِ رَمَضَانَ: يُنْفَى بِذَلِكَ."]]},{"id":"qa16_3","label":"الْأَصْلُ الرَّابِعُ: الِاسْتِصْحَابُ · ٣","segs":[["matn","وَأَمَّا اسْتِصْحَابُ الْإِجْمَاعِ فِي مِثْلِ قَوْلِهِمُ: الْإِجْمَاعُ عَلَى صِحَّةِ صَلَاةِ الْمُتَيَمِّمِ، فَإِذَا رَأَى الْمَاءَ فِي أَثْنَاءِ الصَّلَاةِ لَمْ تَبْطُلِ؛ اسْتِصْحَابًا لِلْإِجْمَاعِ: فَفَاسِدٌ عِنْدَ الْأَكْثَرِينَ. خِلَافًا لِابْنِ شَاقْلَا، وَبَعْضِ الْفُقَهَاءِ. فَهَذِهِ الْأُصُولُ الْأَرْبَعَةُ: لَا خِلَافَ فِيهَا."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa17","title":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا","units":[{"id":"qa17_1","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ١","segs":[["matn","وَقَدِ اخْتُلِفَ فِي أُصُولٍ أَرْبَعَةٍ أُخَرَ، وَهِيَ: شَرْعُ مَنْ قَبْلَنَا: وَهُوَ شَرْعٌ لَنَا، مَا لَمْ يَرِدْ نَسْخُهُ فِي إِحْدَى الرِّوَايَتَيْنِ، اخْتَارَهَا التَّمِيمِيُّ، وَهُوَ قَوْلُ بَعْضِ الْحَنَفِيَّةِ، وَبَعْضِ الشَّافِعِيَّةِ."]]},{"id":"qa17_2","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ٢","segs":[["matn","وَالْأُخْرَى: لَا، وَهِيَ قَوْلُ الْأَكْثَرِينَ. وَقَوْلُ الصَّحَابِيِّ إِذَا لَمْ يَظْهَرْ لَهُ مُخَالِفٌ: فَرُوِيَ أَنَّهُ: حُجَّةٌ. يُقَدَّمُ عَلَى الْقِيَاسِ. وَيُخَصُّ بِهِ الْعُمُومُ. وَهُوَ قَوْلُ مَالِكٍ، وَقَدِيمُ قَوْلَيِ الشَّافِعِيِّ، وَبَعْضِ الْحَنَفِيَّةِ."]]},{"id":"qa17_3","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ٣","segs":[["matn","وَيُرْوَى: خِلَافُهُ، وَهُوَ قَوْلُ عَامَّةِ الْمُتَكَلِّمِينَ، وَجَدِيدُ قَوْلَيِ الشَّافِعِيِّ، وَاخْتَارَهُ أَبُو الْخَطَّابِ. وَقِيلَ: الْخُلَفَاءُ الْأَرْبَعَةُ. وَقِيلَ: أَبُو بَكْرٍ، وَعُمَرُ."]]},{"id":"qa17_4","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ٤","segs":[["matn","فَإِنِ اخْتَلَفَ الصَّحَابَةُ عَلَى قَوْلَيْنِ: لَمْ يَجُزْ لِلْمُجْتَهِدِ الْأَخْذُ بِأَحَدِهِمَا إِلَّا بِدَلِيلٍ. وَأَجَازَهُ بَعْضُ الْحَنَفِيَّةِ وَالْمُتَكَلِّمِينَ مَا لَمْ يُنْكَرْ عَلَى الْقَائِلِ قَوْلُهُ."]]},{"id":"qa17_5","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ٥","segs":[["matn","وَالِاسْتِحْسَانُ: وَهُوَ الْعُدُولُ بِحُكْمِ الْمَسْأَلَةِ عَنْ نَظَائِرِهَا لِدَلِيلٍ خَاصٍّ. قَالَ الْقَاضِي: الِاسْتِحْسَانُ مَذْهَبُ أَحْمَدَ رَحِمَهُ اللَّهُ: وَهُوَ أَنْ يَتْرُكَ حُكْمًا إِلَى حُكْمٍ هُوَ أَوْلَى مِنْهُ. وَهَذَا لَا يُنْكِرُهُ أَحَدٌ."]]},{"id":"qa17_6","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ٦","segs":[["matn","وَقِيلَ: دَلِيلٌ يَنْقَدِحُ فِي نَفْسِ الْمُجْتَهِدِ، لَا يُمْكِنُهُ التَّعْبِيرُ عَنْهُ. وَلَيْسَ بِشَيْءٍ. وَقِيلَ: مَا اسْتَحْسَنَهُ الْمُجْتَهِدُ بِعَقْلِهِ. وَحُكِيَ عَنْ أَبِي حَنِيفَةَ: أَنَّهُ حُجَّةٌ؛ كَدُخُولِ الْحَمَّامِ بِغَيْرِ تَقْدِيرِ أُجْرَةٍ، وَشِبْهِهِ."]]},{"id":"qa17_7","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ٧","segs":[["matn","وَالِاسْتِصْلَاحُ: وَهُوَ اتِّبَاعُ الْمَصْلَحَةِ الْمُرْسَلَةِ مِنْ جَلْبِ مَنْفَعَةٍ أَوْ دَفْعِ مَضَرَّةٍ، مِنْ غَيْرِ أَنْ يَشْهَدَ لَهَا أَصْلٌ شَرْعِيٌّ. وَهِيَ: إِمَّا ضَرُورِيٌّ: كَقَتْلِ الْكَافِرِ الْمُضِلِّ، وَعُقُوبَةِ الْمُبْتَدِعِ الدَّاعِي؛ حِفْظًا لِلدِّينِ."]]},{"id":"qa17_8","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ٨","segs":[["matn","وَالْقِصَاصِ؛ حِفْظًا لِلنَّفْسِ. وَحَدِّ الشُّرْبِ؛ حِفْظًا لِلْعَقْلِ. وَحَدِّ الزِّنَى؛ حِفْظًا لِلنَّسَبِ. وَالْقَطْعِ حِفْظًا لِلْمَالِ. فَذَهَبَ مَالِكٌ، وَبَعْضُ الشَّافِعِيَّةِ: إِلَى أَنَّ هَذِهِ الْمَصْلَحَةَ حُجَّةٌ. وَالصَّحِيحُ: أَنَّهُ لَيْسَ بِحُجَّةٍ."]]},{"id":"qa17_9","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ٩","segs":[["matn","وَإِمَّا حَاجِيٌّ: كَتَسْلِيطِ الْوَلِيِّ عَلَى تَزْوِيجِ الصَّغِيرَةِ لِتَحْصِيلِ الْكُفْءِ؛ خِيفَةَ الْفَوَاتِ. أَوْ تَحْسِينِيٌّ: كَالْوَلِيِّ فِي النِّكَاحِ؛ صِيَانَةً لِلْمَرْأَةِ عَنْ مُبَاشَرَةِ الْعَقْدِ الدَّالِّ عَلَى الْمَيْلِ إِلَى الرِّجَالِ."]]},{"id":"qa17_10","label":"الْأُصُولُ الْمُخْتَلَفُ فِيهَا · ١٠","segs":[["matn","فَهَذَانِ لَا يُتَمَسَّكُ بِهِمَا بِدُونِ أَصْلٍ بِلَا خِلَافٍ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa18","title":"الْقِيَاسُ","units":[{"id":"qa18_1","label":"الْقِيَاسُ · ١","segs":[["matn","وَمِمَّا يَتَفَرَّعُ عَنِ الْأُصُولِ الْمُتَقَدِّمَةِ: الْقِيَاسُ. وَأَصْلُهُ: التَّقْدِيرُ. وَهُوَ: حَمْلُ فَرْعٍ عَلَى أَصْلٍ فِي حُكْمٍ؛ لِجَامِعٍ بَيْنَهُمَا. وَقِيلَ: إِثْبَاتُ حُكْمِ الْأَصْلِ فِي الْفَرْعِ؛ لِاشْتِرَاكِهِمَا فِي عِلَّةِ الْحُكْمِ."]]},{"id":"qa18_2","label":"الْقِيَاسُ · ٢","segs":[["matn","وَقِيلَ: حَمْلُ مَعْلُومٍ عَلَى مَعْلُومٍ فِي إِثْبَاتِ حُكْمٍ لَهُمَا، أَوْ نَفْيِهِ عَنْهُمَا؛ لِجَامِعٍ بَيْنَهُمَا، مِنْ إِثْبَاتِ حُكْمٍ أَوْ صِفَةٍ لَهُمَا، أَوْ نَفْيِهِ عَنْهُمَا. وَهُوَ بِمَعْنَى الْأَوَّلِ، وَذَاكَ أَوْجَزُ."]]},{"id":"qa18_3","label":"الْقِيَاسُ · ٣","segs":[["matn","وَقِيلَ: هُوَ الِاجْتِهَادُ. وَهُوَ خَطَأٌ. وَالتَّعَبُّدُ بِهِ جَائِزٌ عَقْلًا وَشَرْعًا، عِنْدَ عَامَّةِ الْفُقَهَاءِ وَالْمُتَكَلِّمِينَ. خِلَافًا لِلظَّاهِرِيَّةِ، وَالنَّظَّامِ. وَيَجْرِي فِي جَمِيعِ الْأَحْكَامِ. حَتَّى فِي الْحُدُودِ وَالْكَفَّارَاتِ. خِلَافًا لِلْحَنَفِيَّةِ."]]},{"id":"qa18_4","label":"الْقِيَاسُ · ٤","segs":[["matn","وَفِي الْأَسْبَابِ عِنْدَ الْجُمْهُورِ. وَمَنَعَهُ بَعْضُ الْحَنَفِيَّةِ. ثُمَّ إِلْحَاقُ الْمَسْكُوتِ بِالْمَنْطُوقِ: مَقْطُوعٌ. وَهُوَ مَفْهُومُ الْمُوَافَقَةِ، وَقَدْ سَبَقَ. وَضَابِطُهُ: أَنَّهُ يَكْفِي فِيهِ نَفْيُ الْفَارِقِ الْمُؤَثِّرِ، مِنْ غَيْرِ تَعَرُّضٍ لِلْعِلَّةِ."]]},{"id":"qa18_5","label":"الْقِيَاسُ · ٥","segs":[["matn","وَمَا عَدَاهُ: فَهُوَ مَظْنُونٌ. وَلِلْإِلْحَاقِ فِيهِ طَرِيقَانِ: أَحَدُهُمَا: نَفْيُ الْفَارِقِ الْمُؤَثِّرِ. وَإِنَّمَا يَحْسُنُ مَعَ التَّقَارُبِ. وَالثَّانِي: بِالْجَامِعِ فِيهِمَا، وَهُوَ الْقِيَاسُ."]]},{"id":"qa18_6","label":"الْقِيَاسُ · ٦","segs":[["matn","فَإِذَنْ؛ أَرْكَانُ الْقِيَاسِ أَرْبَعَةٌ: الْأَصْلُ: وَهُوَ الْمَحَلُّ الثَّابِتُ الْحُكْمِ، الْمُلْحَقُ بِهِ؛ كَالْخَمْرِ مَعَ النَّبِيذِ. وَشَرْطُهُ: أَنْ يَكُونَ مَعْقُولَ الْمَعْنَى؛ لِيَتَعَدَّى. فَإِنْ كَانَ تَعَبُّدِيًّا: لَمْ يَصِحَّ. وَمُوَافَقَةُ الْخَصْمِ عَلَيْهِ."]]},{"id":"qa18_7","label":"الْقِيَاسُ · ٧","segs":[["matn","فَإِنْ مَنَعَهُ، وَأَمْكَنَهُ إِثْبَاتُهُ بِالنَّصِّ: جَازَ، لَا بِعِلَّةٍ عِنْدَ الْمُحَقِّقِينَ. وَقِيلَ: الِاتِّفَاقُ شَرْطٌ. وَالْفَرْعُ: وَهُوَ لُغَةً: مَا تَوَلَّدَ عَنْ غَيْرِهِ، وَانْبَنَى عَلَيْهِ. وَهُنَا: الْمَحَلُّ الْمَطْلُوبُ إِلْحَاقُهُ."]]},{"id":"qa18_8","label":"الْقِيَاسُ · ٨","segs":[["matn","وَشَرْطُهُ: وُجُودُ عِلَّةِ الْأَصْلِ فِيهِ. وَالْحُكْمُ: وَهُوَ الْوَصْفُ الْمَقْصُودُ بِالْإِلْحَاقِ. فَالْإِثْبَاتُ: رُكْنٌ لِكُلِّ قِيَاسٍ. وَالنَّفْيُ، إِلَّا لِقِيَاسِ الْعِلَّةِ عِنْدَ الْمُحَقِّقِينَ؛ لِاشْتِرَاطِ الْوُجُودِ فِيهَا. وَشَرْطُهُ: الِاتِّحَادُ فِيهَا: قَدْرًا. وَصِفَةً."]]},{"id":"qa18_9","label":"الْقِيَاسُ · ٩","segs":[["matn","وَأَنْ يَكُونَ شَرْعِيًّا. لَا عَقْلِيًّا. أَوْ أُصُولِيًّا. وَالْجَامِعُ: وَهُوَ الْمُقْتَضِي لِإِثْبَاتِ الْحُكْمِ. وَيَكُونُ حُكْمًا شَرْعِيًّا. وَوَصْفًا عَارِضًا. وَلَازِمًا. وَمُفْرَدًا. وَمُرَكَّبًا. وَفِعْلًا. وَنَفْيًا. وَإِثْبَاتًا. وَمُنَاسِبًا. وَغَيْرَ مُنَاسِبٍ."]]},{"id":"qa18_10","label":"الْقِيَاسُ · ١٠","segs":[["matn","وَقَدْ لَا يَكُونُ مَوْجُودًا فِي مَحَلِّ الْحُكْمِ؛ كَتَحْرِيمِ نِكَاحِ الْحُرِّ لِلْأَمَةِ؛ لِعِلَّةِ رِقِّ الْوَلَدِ. وَلَهُ أَلْقَابٌ، مِنْهَا: الْعِلَّةُ: وَقَدْ سَبَقَ تَفْسِيرُهَا. وَالْمُؤَثِّرُ: وَهُوَ الْمَعْنَى الَّذِي عُرِفَ كَوْنُهُ مَنَاطًا لِلْحُكْمِ بِمُنَاسَبَتِهِ."]]},{"id":"qa18_11","label":"الْقِيَاسُ · ١١","segs":[["matn","وَالْمَنَاطُ: وَهُوَ مِنْ تَعَلُّقِ الشَّيْءِ بِالشَّيْءِ، وَمِنْهُ: نِيَاطُ الْقَلْبِ؛ لِعَلَّاقَتِهِ، فَلِذَلِكَ هُوَ عِنْدَ الْفُقَهَاءِ مُتَعَلَّقُ الْحُكْمِ. وَالْبَحْثُ فِيهِ: إِمَّا لِوُجُودِهِ، وَهُوَ: تَحْقِيقُ الْمَنَاطِ."]]},{"id":"qa18_12","label":"الْقِيَاسُ · ١٢","segs":[["matn","أَوْ تَنْقِيَتِهِ وَتَخْلِيصِهِ مِنْ غَيْرِهِ، وَهُوَ: تَنْقِيحُ الْمَنَاطِ. أَنْ يَنُصَّ الشَّارِعُ عَلَى حُكْمٍ عَقِيبَ أَوْصَافٍ، فَيُلْغِيَ الْمُجْتَهِدُ غَيْرَ الْمُؤَثِّرِ، وَيُعَلِّقَ الْحُكْمَ عَلَى مَا بَقِيَ."]]},{"id":"qa18_13","label":"الْقِيَاسُ · ١٣","segs":[["matn","وَتَخْرِيجُهُ: بِأَنْ يَنُصَّ الشَّارِعُ عَلَى حُكْمٍ غَيْرِ مُقْتَرِنٍ بِمَا يَصْلُحُ عِلَّةً، فَيَسْتَخْرِجَ الْمُجْتَهِدُ عِلَّتَهُ بِاجْتِهَادِهِ وَنَظَرِهِ. وَالْمَظِنَّةُ: وَهِيَ مِنْ «ظَنَنْتُ الشَّيْءَ»."]]},{"id":"qa18_14","label":"الْقِيَاسُ · ١٤","segs":[["matn","وَقَدْ تَكُونُ بِمَعْنَى الْعِلْمِ؛ كَمَا فِي قَوْلِهِ تَعَالَى: ﴿الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلَاقُو رَبِّهِمْ﴾. وَتَارَةً بِمَعْنَى رُجْحَانِ الِاحْتِمَالِ."]]},{"id":"qa18_15","label":"الْقِيَاسُ · ١٥","segs":[["matn","فَلِذَلِكَ: هِيَ الْأَمْرُ الْمُشْتَمِلُ عَلَى الْحِكْمَةِ الْبَاعِثَةِ عَلَى الْحُكْمِ: إِمَّا قَطْعًا؛ كَالْمَشَقَّةِ فِي السَّفَرِ. أَوِ احْتِمَالًا؛ كَوَطْءِ الزَّوْجَةِ بَعْدَ الْعَقْدِ فِي لُحُوقِ النَّسَبِ. فَمَا خَلَا عَنِ الْحِكْمَةِ: فَلَيْسَ بِمَظِنَّةٍ."]]},{"id":"qa18_16","label":"الْقِيَاسُ · ١٦","segs":[["matn","وَالسَّبَبُ: وَأَصْلُهُ مَا تُوُصِّلَ بِهِ إِلَى مَا لَا يَحْصُلُ بِالْمُبَاشَرَةِ. وَالْمُتَسَبِّبُ: الْمُتَعَاطِي لِفِعْلِهِ. وَهُنَا: مَا تُوُصِّلَ بِهِ إِلَى مَعْرِفَةِ الْحُكْمِ الشَّرْعِيِّ فِيمَا لَا نَصَّ فِيهِ."]]},{"id":"qa18_17","label":"الْقِيَاسُ · ١٧","segs":[["matn","وَجُزْءُ السَّبَبِ: هُوَ الْوَاحِدُ مِنْ أَوْصَافِهِ، كَجُزْءِ الْعِلَّةِ. وَالْمُقْتَضِي: وَهُوَ لُغَةً: طَالِبُ الْقَضَاءِ. فَيُطْلَقُ هُنَا: لِاقْتِضَائِهِ ثُبُوتَ الْحُكْمِ. وَالْمُسْتَدْعِي: وَهُوَ مِنْ «دَعَوْتُهُ إِلَى كَذَا» أَيْ: حَثَثْتُهُ عَلَيْهِ؛ لِاسْتِدْعَائِهِ الْحُكْمَ."]]},{"id":"qa18_18","label":"الْقِيَاسُ · ١٨","segs":[["matn","ثُمَّ الْجَامِعُ: إِنْ كَانَ وَصْفًا، مَوْجُودًا، ظَاهِرًا، مُنْضَبِطًا، مُنَاسِبًا، مُعْتَبَرًا، مُطَّرِدًا، مُتَعَدِّيًا: فَهُوَ عِلَّةٌ لَا خِلَافَ فِي ثُبُوتِ الْحُكْمِ بِهِ."]]},{"id":"qa18_19","label":"الْقِيَاسُ · ١٩","segs":[["matn","أَمَّا الْوُجُودُ: فَشَرْطٌ عِنْدَ الْمُحَقِّقِينَ، لِاسْتِمْرَارِ الْعَدَمِ، فَلَا يَكُونُ عِلَّةً لِلْوُجُودِ. وَأَمَّا النَّفْيُ: فَقِيلَ: يَجُوزُ عِلَّةً. وَلَا خِلَافَ فِي جَوَازِ الِاسْتِدْلَالِ بِالنَّفْيِ عَلَى النَّفْيِ: أَمَّا إِنْ قِيلَ: بِعِلِّيَّتِهِ فَظَاهِرٌ."]]},{"id":"qa18_20","label":"الْقِيَاسُ · ٢٠","segs":[["matn","وَإِلَّا فَمِنْ جِهَةِ الْبَقَاءِ عَلَى الْأَصْلِ، فَيَصِحُّ فِيمَا يَتَوَقَّفُ عَلَى وُجُودِ الْأَمْرِ الْمُدَّعَى انْتِفَاؤُهُ، فَيَنْتَفِي لِانْتِفَاءِ شَرْطِهِ، لَا فِي غَيْرِهِ. وَالظُّهُورُ. وَالِانْضِبَاطُ؛ لِيَتَعَيَّنَ."]]},{"id":"qa18_21","label":"الْقِيَاسُ · ٢١","segs":[["matn","وَالْمُنَاسَبَةُ: وَهِيَ حُصُولُ مَصْلَحَةٍ يَغْلِبُ ظَنُّ الْقَصْدِ لِتَحْصِيلِهَا بِالْحُكْمِ؛ كَالْحَاجَةِ مَعَ الْبَيْعِ. وَغَيْرُهُ: طَرْدِيٌّ: لَيْسَ بِعِلَّةٍ عِنْدَ الْأَكْثَرِينَ. وَقَالَ بَعْضُ الشَّافِعِيَّةِ: يَصِحُّ مُطْلَقًا. وَقِيلَ: جَدَلًا."]]},{"id":"qa18_22","label":"الْقِيَاسُ · ٢٢","segs":[["matn","وَالِاعْتِبَارُ: أَنْ يَكُونَ الْمُنَاسِبُ مُعْتَبَرًا فِي مَوْضِعٍ آخَرَ. وَإِلَّا: فَهُوَ مُرْسَلٌ يَمْتَنِعُ الِاحْتِجَاجُ بِهِ عِنْدَ الْجُمْهُورِ. وَالِاطِّرَادُ: شَرْطٌ عِنْدَ الْقَاضِي، وَبَعْضِ الشَّافِعِيَّةِ. وَقَالَ أَبُو الْخَطَّابِ، وَبَعْضُ الشَّافِعِيَّةِ: يَخْتَصُّ بِمَوْرِدِهِ."]]},{"id":"qa18_23","label":"الْقِيَاسُ · ٢٣","segs":[["matn","وَالتَّخَلُّفُ: إِمَّا لِاسْتِثْنَاءٍ؛ كَالتَّمْرِ فِي الْمُصَرَّاةِ. أَوِ لِمُعَارَضَةِ عِلَّةٍ أُخْرَى. أَوْ لِعَدَمِ الْمَحَلِّ. أَوْ فَوَاتِ شَرْطِهِ. فَلَا يَنْقُضُ، وَمَا سِوَاهُ فَنَاقِضٌ. وَالتَّعَدِّي؛ لِأَنَّهُ الْغَرَضُ مِنَ الْمُسْتَنْبَطَةِ."]]},{"id":"qa18_24","label":"الْقِيَاسُ · ٢٤","segs":[["matn","فَأَمَّا الْقَاصِرَةُ، وَهِيَ: مَا لَا تُوجَدُ فِي غَيْرِ مَحَلِّ النَّصِّ؛ كَالثَّمَنِيَّةِ فِي النَّقْدَيْنِ: فَغَيْرُ مُعْتَبَرَةٍ، وَهُوَ قَوْلُ الْحَنَفِيَّةِ. خِلَافًا لِأَبِي الْخَطَّابِ، وَالشَّافِعِيَّةِ."]]},{"id":"qa18_25","label":"الْقِيَاسُ · ٢٥","segs":[["matn","فَإِنْ لَمْ يَشْهَدْ لَهَا إِلَّا أَصْلٌ وَاحِدٌ؛ فَهُوَ: الْمُنَاسِبُ الْغَرِيبُ."]]},{"id":"qa18_26","label":"الْقِيَاسُ · ٢٦","segs":[["matn","وَإِنْ كَانَ حُكْمًا شَرْعِيًّا: فَالْمُحَقِّقُونَ: تَجُوزُ عِلِّيَّتُهُ؛ لِقَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أَرَأَيْتَ لَوْ كَانَ عَلَى أَبِيكَ دَيْنٌ»، «أَرَأَيْتَ لَوْ تَمَضْمَضْتَ»، فَنَبَّهَ بِحُكْمٍ عَلَى حُكْمٍ. وَقِيلَ: لَا."]]},{"id":"qa18_27","label":"الْقِيَاسُ · ٢٧","segs":[["matn","ثُمَّ هَلْ يُشْتَرَطُ انْعِكَاسُ الْعِلَّةِ؟ فَعِنْدَ الْمُحَقِّقِينَ: لَا يُشْتَرَطُ مُطْلَقًا. وَالْحَقُّ: أَنَّهُ لَا يُشْتَرَطُ إِذَا كَانَ لَهُ عِلَّةٌ أُخْرَى."]]},{"id":"qa18_28","label":"الْقِيَاسُ · ٢٨","segs":[["matn","وَتَعْلِيلُ الْحُكْمِ بِعِلَّتَيْنِ: فِي مَحَلَّيْنِ أَوْ زَمَانَيْنِ: جَائِزٌ اتِّفَاقًا؛ كَتَحْرِيمِ وَطْءِ الزَّوْجَةِ تَارَةً لِلْحَيْضِ، وَتَارَةً لِلْإِحْرَامِ. فَأَمَّا مَعَ اتِّحَادِ الْمَحَلِّ أَوِ الزَّمَانِ: فَالْأَشْبَهُ بِقَوْلِ أَصْحَابِنَا، وَهُوَ قَوْلُ بَعْضِ الشَّافِعِيَّةِ: يَجُوزُ."]]},{"id":"qa18_29","label":"الْقِيَاسُ · ٢٩","segs":[["matn","وَقِيلَ: يُضَافُ إِلَى إِحْدَاهُمَا. وَالصَّحِيحُ: بِهِمَا مَعَ التَّكَافُؤِ، وَإِلَّا الْأَقْوَى مَعَ اتِّحَادِ الزَّمَانِ أَوِ الْمُتَقَدِّمِ. وَثُبُوتُ الْحُكْمِ فِي مَحَلِّ النَّصِّ: بِالنَّصِّ عِنْدَ أَصْحَابِنَا وَالْحَنَفِيَّةِ؛ لِوُجُوبِ قَبُولِهِ، وَإِنْ لَمْ تُعْرَفْ عِلَّتُهُ."]]},{"id":"qa18_30","label":"الْقِيَاسُ · ٣٠","segs":[["matn","وَعِنْدَ الشَّافِعِيَّةِ: بِالْعِلَّةِ. وَالْأَكْثَرُونَ: أَنَّ أَوْصَافَ الْعِلَّةِ لَا تَنْحَصِرُ فِي عَدَدٍ. وَقِيلَ: إِلَى خَمْسَةٍ. وَلِإِثْبَاتِ الْعِلَّةِ طُرُقٌ ثَلَاثَةٌ: النَّصُّ: بِأَنْ يَدُلَّ عَلَيْهَا: بِالصَّرِيحِ: كَقَوْلِهِ: الْعِلَّةُ كَذَا."]]},{"id":"qa18_31","label":"الْقِيَاسُ · ٣١","segs":[["matn","أَوْ بِأَدَوَاتِهَا، وَهِيَ الْبَاءُ: كَقَوْلِهِ: ﴿ذَلِكَ بِأَنَّهُمْ كَفَرُوا﴾. وَاللَّامُ: ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ﴾. وَكَيْ: ﴿كَيْ لَا يَكُونَ دُوْلَةً﴾. وَحَتَّى: نَحْوُ: ﴿حَتَّى لَا تَكُونَ فِتْنَةٌ﴾."]]},{"id":"qa18_32","label":"الْقِيَاسُ · ٣٢","segs":[["matn","وَمِنْ أَجْلِ: نَحْوُ: ﴿مِنْ أَجْلِ ذَلِكَ كَتَبْنَا﴾. أَوْ بِالتَّنْبِيهِ وَالْإِيمَاءِ: إِمَّا بِالْفَاءِ: وَتَدْخُلُ: عَلَى السَّبَبِ؛ كَقَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «فَإِنَّهُ يُبْعَثُ مُلَبِّيًا»."]]},{"id":"qa18_33","label":"الْقِيَاسُ · ٣٣","segs":[["matn","وَعَلَى الْحُكْمِ؛ مِثْلُ: ﴿وِالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا﴾، وَ«سَهَا فَسَجَدَ»، وَ«زَنَى فَرُجِمَ». أَوْ تَرْتِيبِهِ عَلَى وَاقِعَةٍ سُئِلَ عَنْهَا؛ كَقَوْلِهِ: «أَعْتِقْ رَقَبَةً» فِي جَوَابِ سُؤَالِهِ عَنِ الْمُوَاقَعَةِ فِي نَهَارِ رَمَضَانَ."]]},{"id":"qa18_34","label":"الْقِيَاسُ · ٣٤","segs":[["matn","أَوْ لِعَدَمِ فَائِدَتِهِ إِنْ لَمْ يَكُنْ عِلَّةً؛ كَقَوْلِهِ: «إِنَّهَا مِنَ الطَّوَّافِينَ عَلَيْكُمْ». أَوْ نَفْيِ حُكْمٍ بَعْدَ ثُبُوتِهِ لِحُدُوثِ وَصْفٍ؛ كَقَوْلِهِ: «لَا يَرِثُ الْقَاتِلُ»."]]},{"id":"qa18_35","label":"الْقِيَاسُ · ٣٥","segs":[["matn","أَوِ الِامْتِنَاعِ عَنْ فِعْلٍ بَعْدَ فِعْلِ مِثْلِهِ لِعُذْرٍ؛ فَيَدُلُّ عَلَى عِلِّيَّةِ الْعُذْرِ؛ كَامْتِنَاعِهِ عَنْ دُخُولِ بَيْتٍ فِيهِ كَلْبٌ. أَوْ تَعْلِيقِهِ عَلَى اسْمٍ مُشْتَقٍّ مِنْ وَصْفٍ مُنَاسِبٍ لَهُ؛ كَقَوْلِهِ: ﴿فَاقْتُلُوا الْمُشْرِكِينَ﴾."]]},{"id":"qa18_36","label":"الْقِيَاسُ · ٣٦","segs":[["matn","أَوْ إِثْبَاتِ حُكْمٍ إِنْ لَمْ يُجْعَلْ عِلَّةً لِحُكْمٍ آخَرَ لَمْ يَكُنْ مُفِيدًا؛ كَقَوْلِهِ تَعَالَى: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ﴾؛ لِصِحَّتِهِ، ﴿وَحَرَّمَ الرِّبَا﴾؛ لِبُطْلَانِهِ. وَالْإِجْمَاعُ: فَمَتَى وُجِدَ الِاتِّفَاقُ عَلَيْهِ -وَلَوْ مِنَ الْخَصْمَيْنِ-: ثَبَتَ."]]},{"id":"qa18_37","label":"الْقِيَاسُ · ٣٧","segs":[["matn","وَالِاسْتِنْبَاطُ: إِمَّا بِالْمُنَاسَبَةِ: وَهِيَ حُصُولُ الْمَصْلَحَةِ فِي إِثْبَاتِ الْحُكْمِ مِنَ الْوَصْفِ؛ كَالْحَاجَةِ مَعَ الْبَيْعِ. وَلَا يُعْتَبَرُ كَوْنُهَا مَنْشَأَ الْحِكْمَةِ."]]},{"id":"qa18_38","label":"الْقِيَاسُ · ٣٨","segs":[["matn","وَالْمُؤَثِّرُ: مَا ظَهَرَ تَأْثِيرُهُ فِي الْحُكْمِ بِنَصٍّ أَوْ إِجْمَاعٍ، وَهُوَ ثَلَاثَةٌ: الْمُنَاسِبُ الْمُطْلَقُ. وَالْمُلَائِمُ. وَالْغَرِيبُ. وَقَدْ قَصَرَ قَوْمٌ الْقِيَاسَ عَلَى الْمُؤَثِّرِ وَحْدَهُ."]]},{"id":"qa18_39","label":"الْقِيَاسُ · ٣٩","segs":[["matn","وَأُصُولُ الْمَصَالِحِ خَمْسَةٌ: ثَلَاثَةٌ مِنْهَا ذُكِرَتْ فِي الِاسْتِصْلَاحِ: وَهِيَ الْمُعْتَبَرَةُ. وَالرَّابِعُ: مَا لَمْ يُعْلَمْ مِنَ الشَّرْعِ الِالْتِفَاتُ إِلَيْهِ وَلَا إِلْغَاؤُهُ: فَلَا بُدَّ مِنْ شَهَادَةِ أَصْلٍ لَهُ."]]},{"id":"qa18_40","label":"الْقِيَاسُ · ٤٠","segs":[["matn","وَالْخَامِسُ: مَا عُلِمَ مِنَ الشَّرْعِ إِلْغَاؤُهُ: فَهُوَ مُلْغًى بِذَلِكَ. أَوْ بِالسَّبْرِ وَالتَّقْسِيمِ: بِحَصْرِ الْعِلَلِ، وَإِبْطَالِ مَا عَدَا الْمُدَّعَى عِلَّةً. أَوْ بِقِيَاسِ الشَّبَهِ."]]},{"id":"qa18_41","label":"الْقِيَاسُ · ٤١","segs":[["matn","أَوْ بِنَفْيِ الْفَارِقِ بَيْنَ الْأَصْلِ وَالْفَرْعِ إِلَّا بِمَا لَا أَثَرَ لَهُ، وَهُوَ مُثْبِتٌ لِلْعِلَّةِ، لِدَلَالَتِهِ عَلَى الِاشْتِرَاكِ فِيهَا عَلَى الْإِجْمَالِ."]]},{"id":"qa18_42","label":"الْقِيَاسُ · ٤٢","segs":[["matn","وَقَدِ اسْتُدِلَّ عَلَى إِثْبَاتِ الْعِلَّةِ بِمَسَالِكَ فَاسِدَةٍ: كَقَوْلِهِمْ: سَلَامَةُ الْوَصْفِ مِنْ مُنَاقِضٍ لَهُ دَلِيلُ عِلِّيَّتِهِ. وَغَايَتُهُ: سَلَامَتُهُ مِنَ الْمُعَارَضَةِ، وَهِيَ إِحْدَى الْمُفْسِدَاتِ، وَلَوْ سَلِمَ مِنْ كُلِّهَا لَمْ يَثْبُتْ."]]},{"id":"qa18_43","label":"الْقِيَاسُ · ٤٣","segs":[["matn","وَمِنْهَا: الطَّرْدُ، وَهُوَ قَوْلُهُمْ: ثُبُوتُ الْحُكْمِ مَعَهُ أَيْنَمَا وُجِدَ دَلِيلُ عِلِّيَّتِهِ. وَمِنْهَا: الدَّوَرَانُ، وَهُوَ وُجُودُ الْحُكْمِ مَعَهَا، وَعَدَمُهُ بِعَدَمِهَا. فَقِيلَ: صَحِيحٌ؛ لِأَنَّهُ أَمَارَةٌ. وَقِيلَ: فَاسِدٌ؛ لِأَنَّهُ طَرْدٌ."]]},{"id":"qa18_44","label":"الْقِيَاسُ · ٤٤","segs":[["matn","وَالْعَكْسُ لَا يُؤَثِّرُ؛ لِعَدَمِ اشْتِرَاطِهِ. وَوُجُودُ مَفْسَدَةٍ فِي الْوَصْفِ مُسَاوِيَةٍ أَوْ رَاجِحَةٍ: قِيلَ: يَخْرِمُ مُنَاسَبَتَهُ. وَقِيلَ: لَا."]]},{"id":"qa18_45","label":"الْقِيَاسُ · ٤٥","segs":[["matn","وَقَالَ النَّظَّامُ: يَجِبُ الْإِلْحَاقُ بِالْعِلَّةِ الْمَنْصُوصِ عَلَيْهَا بِالْعُمُومِ اللَّفْظِيِّ، لَا بِالْقِيَاسِ؛ إِذْ لَا فَرْقَ لُغَةً بَيْنَ: «حَرَّمْتُ الْخَمْرَ لِشِدَّتِهَا»، وَبَيْنَ: «حَرَّمْتُ كُلَّ مُشْتَدٍّ»."]]},{"id":"qa18_46","label":"الْقِيَاسُ · ٤٦","segs":[["matn","وَهُوَ خَطَأٌ؛ لِعَدَمِ تَنَاوُلِ: «حَرَّمْتُ الْخَمْرَ لِشِدَّتِهَا» كُلَّ مُشْتَدٍّ غَيْرَهَا، وَلَوْلَا الْقِيَاسُ لَاقْتَصَرْنَا عَلَيْهِ، فَيَكُونُ فَائِدَةُ التَّعْلِيلِ: دَوَرَانَ التَّحْرِيمِ مَعَ الشِّدَّةِ."]]},{"id":"qa18_47","label":"الْقِيَاسُ · ٤٧","segs":[["matn","وَأَنْوَاعُ الْقِيَاسِ أَرْبَعَةٌ: قِيَاسُ الْعِلَّةِ: وَهُوَ مَا جُمِعَ فِيهِ بِالْعِلَّةِ نَفْسِهَا. وَقِيَاسُ الدَّلَالَةِ: وَهُوَ مَا جُمِعَ فِيهِ بِدَلِيلِ الْعِلَّةِ؛ لِيَلْزَمَ مِنِ اشْتِرَاكِهِمَا فِيهِ وُجُودُهَا."]]},{"id":"qa18_48","label":"الْقِيَاسُ · ٤٨","segs":[["matn","وَقِيَاسُ الشَّبَهِ: وَقَدِ اخْتُلِفَ فِي تَفْسِيرِهِ: فَقَالَ الْقَاضِي يَعْقُوبُ: هُوَ أَنْ يَتَرَدَّدَ الْفَرْعُ بَيْنَ حَاظِرٍ وَمُبِيحٍ، فَيُلْحَقَ بِأَكْثَرِهِمَا شَبَهًا."]]},{"id":"qa18_49","label":"الْقِيَاسُ · ٤٩","segs":[["matn","وَقِيلَ: هُوَ الْجَمْعُ بِوَصْفٍ يُوهِمُ اشْتِمَالَهُ عَلَى الْمَظِنَّةِ مِنْ غَيْرِ وُقُوفٍ عَلَيْهَا. وَهُوَ صَحِيحٌ فِي إِحْدَى الرِّوَايَتَيْنِ، وَأَحَدُ قَوْلَيِ الشَّافِعِيِّ."]]},{"id":"qa18_50","label":"الْقِيَاسُ · ٥٠","segs":[["matn","وَقِيَاسُ الطَّرْدِ: وَهُوَ مَا جُمِعَ فِيهِ بِوَصْفٍ غَيْرِ مُنَاسِبٍ، أَوْ مُلْغًى بِالشَّرْعِ. وَهُوَ بَاطِلٌ. وَأَرْبَعَتُهَا تَجْرِي فِي الْإِثْبَاتِ. وَأَمَّا النَّفْيُ: فَطَارِئٌ؛ كَبَرَاءَةِ الذِّمَّةِ مِنَ الدَّيْنِ: فَيَجْرِي فِيهِ الْأَوَّلَانِ؛ كَالْإِثْبَاتِ."]]},{"id":"qa18_51","label":"الْقِيَاسُ · ٥١","segs":[["matn","وَأَصْلِيٌّ - وَهُوَ الْبَقَاءُ عَلَى مَا كَانَ قَبْلَ الشَّرْعِ -، فَلَيْسَ بِحُكْمٍ شَرْعِيٍّ لِيَقْتَضِيَ عِلَّةً شَرْعِيَّةً: فَيَجْرِي فِيهِ قِيَاسُ الدَّلَالَةِ."]]},{"id":"qa18_52","label":"الْقِيَاسُ · ٥٢","segs":[["matn","وَالْخَطَأُ يَتَطَرَّقُ إِلَى الْقِيَاسِ مِنْ خَمْسَةِ أَوْجُهٍ: أَنْ يَكُونَ الْحُكْمُ تَعَبُّدِيًّا. أَوْ يُخْطِئَ عِلَّتَهُ عِنْدَ اللَّهِ تَعَالَى. أَوْ يُقَصِّرَ فِي بَعْضِ الْأَوْصَافِ. أَوْ يَضُمَّ مَا لَيْسَ مِنَ الْعِلَّةِ إِلَيْهَا."]]},{"id":"qa18_53","label":"الْقِيَاسُ · ٥٣","segs":[["matn","أَوْ يَظُنَّ وُجُودَهَا فِي الْفَرْعِ، وَلَيْسَتْ مَوْجُودَةً فِيهِ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa19","title":"الِاسْتِدْلَالُ","units":[{"id":"qa19_1","label":"الِاسْتِدْلَالُ · ١","segs":[["matn","وَالِاسْتِدْلَالُ: تَرْتِيبُ أُمُورٍ مَعْلُومَةٍ يَلْزَمُ مِنْ تَسْلِيمِهَا تَسْلِيمُ الْمَطْلُوبِ. وَصُوَرُهُ كَثِيرَةٌ: وَمِنْهَا: الْبُرْهَانُ، وَهُوَ ثَلَاثَةٌ: بُرْهَانُ الِاعْتِلَالِ: وَهُوَ قِيَاسٌ بِصُورَةٍ أُخْرَى، تَنْتَظِمُ مِنْ مُقَدِّمَتَيْنِ وَنَتِيجَةٍ."]]},{"id":"qa19_2","label":"الِاسْتِدْلَالُ · ٢","segs":[["matn","وَمَعْنَاهُ: إِدْخَالُ وَاحِدٍ مُعَيَّنٍ تَحْتَ جُمْلَةٍ مَعْلُومَةٍ؛ كَقَوْلِنَا: النَّبِيذُ مُسْكِرٌ، وَكُلُّ مُسْكِرٍ حَرَامٌ، فَيَنْتُجُ: النَّبِيذُ حَرَامٌ."]]},{"id":"qa19_3","label":"الِاسْتِدْلَالُ · ٣","segs":[["matn","وَبُرْهَانُ الِاسْتِدْلَالِ: وَهُوَ أَنْ يُسْتَدَلَّ عَلَى الشَّيْءِ بِمَا لَيْسَ مُوجِبًا لَهُ: إِمَّا بِخَاصِّيَّتِهِ؛ كَالِاسْتِدْلَالِ عَلَى نَفْلِيَّةِ الْوِتْرِ بِجَوَازِ فِعْلِهِ عَلَى الرَّاحِلَةِ. أَوْ بِنَتِيجَتِهِ؛ كَقَوْلِهِ: لَوْ صَحَّ الْبَيْعُ لَأَفَادَ الْمِلْكَ."]]},{"id":"qa19_4","label":"الِاسْتِدْلَالُ · ٤","segs":[["matn","أَوْ بِنَظِيرِهِ: إِمَّا بِالنَّفْيِ عَلَى النَّفْيِ؛ كَقَوْلِهِ: لَوْ صَحَّ التَّعْلِيقُ لَصَحَّ التَّنْجِيزُ. أَوْ بِالْإِثْبَاتِ عَلَى الْإِثْبَاتِ؛ كَقَوْلِهِ: لَوْ لَمْ يَصِحَّ طَلَاقُهُ لَمَا صَحَّ ظِهَارُهُ."]]},{"id":"qa19_5","label":"الِاسْتِدْلَالُ · ٥","segs":[["matn","أَوْ بِالْإِثْبَاتِ عَلَى النَّفْيِ؛ كَقَوْلِهِ: لَوْ كَانَ الْوِتْرُ فَرْضًا لَمَا صَحَّ فِعْلُهُ عَلَى الرَّاحِلَةِ."]]},{"id":"qa19_6","label":"الِاسْتِدْلَالُ · ٦","segs":[["matn","أَوْ بِالنَّفْيِ عَلَى الْإِثْبَاتِ؛ كَقَوْلِهِ: لَوْ لَمْ يَجُزْ تَخْلِيلُ الْخَمْرِ لَحَرُمَ نَقْلُهَا مِنَ الظِّلِّ إِلَى الشَّمْسِ، وَمَا حَرُمَ فَيَجُوزُ. وَيَلْزَمُهُ بَيَانُ التَّلَازُمِ ظَاهِرًا لَا غَيْرُ."]]},{"id":"qa19_7","label":"الِاسْتِدْلَالُ · ٧","segs":[["matn","وَبُرْهَانُ الْخَلْفِ: وَهُوَ كُلُّ شَكْلٍ تَعَرَّضَ فِيهِ بِإِبْطَالِ مَذْهَبِ الْخَصْمِ لِيَلْزَمَ صِحَّةُ مَذْهَبِهِ: إِمَّا بِحَصْرِ الْمَذَاهِبِ وَإِبْطَالِهَا إِلَّا وَاحِدًا. أَوْ يَذْكُرُ أَقْسَامًا ثُمَّ يُبْطِلُهَا كُلَّهَا."]]},{"id":"qa19_8","label":"الِاسْتِدْلَالُ · ٨","segs":[["matn","وَسُمِّيَ خَلْفًا: إِمَّا لِأَنَّهُ لُغَةً: الرَّدِيءُ، وَكُلُّ بَاطِلٍ رَدِيءٌ. أَوْ لِأَنَّهُ الِاسْتِقَاءُ، وَهُوَ اسْتِمْدَادٌ؛ فَكَأَنَّهُ اسْتَمَدَّ صِحَّةَ مَذْهَبِهِ مِنْ فَسَادِ مَذْهَبِ خَصْمِهِ."]]},{"id":"qa19_9","label":"الِاسْتِدْلَالُ · ٩","segs":[["matn","وَيَجُوزُ أَنْ يَكُونَ مِنَ الْخَلْفِ، وَهُوَ الْوَرَاءُ؛ لِعَدَمِ الِالْتِفَاتِ إِلَى مَا بَطَلَ. وَمِنْهَا: ضُرُوبٌ غَيْرُ ذَلِكَ؛ كَقَوْلِهِمْ: وُجِدَ سَبَبُ الْوُجُوبِ، فَيَجِبُ. أَوْ فُقِدَ شَرْطُ الصِّحَّةِ، فَلَا يَصِحُّ."]]},{"id":"qa19_10","label":"الِاسْتِدْلَالُ · ١٠","segs":[["matn","أَوْ لَمْ يُوجَدْ سَبَبُ الْوُجُوبِ، فَلَا يَجِبُ. أَوْ لَا فَارِقَ بَيْنَ كَذَا وَكَذَا إِلَّا كَذَا وَكَذَا، وَلَا أَثَرَ لَهُ. أَوْ لَا نَصَّ وَلَا إِجْمَاعَ وَلَا قِيَاسَ فِي كَذَا، فَلَا يَثْبُتُ."]]},{"id":"qa19_11","label":"الِاسْتِدْلَالُ · ١١","segs":[["matn","أَوِ الدَّلِيلُ يَنْفِي كَذَا، خَالَفْنَاهُ لِكَذَا، فَبَقِيَ عَلَى مُقْتَضَى النَّافِي، وَهَذَا يُعْرَفُ بِالدَّلِيلِ النَّافِي. وَأَشْبَاهِ ذَلِكَ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa20","title":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ","units":[{"id":"qa20_1","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ١","segs":[["matn","فَصْلٌ: وَأَمَّا تَرْتِيبُ الْأَدِلَّةِ وَتَرْجِيحُهَا: فَإِنَّهُ يَبْدَأُ بِالنَّظَرِ فِي الْإِجْمَاعِ: فَإِنْ وُجِدَ: لَمْ يُحْتَجْ إِلَى غَيْرِهِ. فَإِنْ خَالَفَهُ نَصٌّ مِنْ كِتَابٍ أَوْ سُنَّةٍ: عُلِمَ أَنَّهُ: مَنْسُوخٌ. أَوْ مُتَأَوَّلٌ."]]},{"id":"qa20_2","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ٢","segs":[["matn","لِأَنَّ الْإِجْمَاعَ قَاطِعٌ لَا يَقْبَلُ نَسْخًا وَلَا تَأْوِيلًا. ثُمَّ فِي الْكِتَابِ وَالسُّنَّةِ الْمُتَوَاتِرَةِ. وَلَا تَعَارُضَ: فِي الْقَوَاطِعِ، إِلَّا أَنْ يَكُونَ أَحَدُهُمَا مَنْسُوخًا."]]},{"id":"qa20_3","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ٣","segs":[["matn","وَلَا فِي عِلْمٍ وَظَنٍّ؛ لِأَنَّ مَا عُلِمَ لَا يُظَنُّ خِلَافُهُ. ثُمَّ فِي أَخْبَارِ الْآحَادِ. ثُمَّ قِيَاسِ النُّصُوصِ. فَإِنْ تَعَارَضَ قِيَاسَانِ، أَوْ حَدِيثَانِ، أَوْ عُمُومَانِ: فَالتَّرْجِيحُ."]]},{"id":"qa20_4","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ٤","segs":[["matn","وَالتَّعَارُضُ: هُوَ التَّنَاقُضُ، فَلِذَلِكَ لَا يَكُونُ: فِي خَبَرَيْنِ؛ لِأَنَّهُ يَلْزَمُ كَذِبُ أَحَدِهِمَا. وَلَا فِي حُكْمَيْنِ، فَإِنْ وُجِدَ فِيهِمَا: فَإِمَّا لِكَذِبِ الرَّاوِي. أَوْ نَسْخِ أَحَدِهِمَا."]]},{"id":"qa20_5","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ٥","segs":[["matn","فَإِنْ أَمْكَنَ الْجَمْعُ: بِأَنْ يُنَزَّلَ عَلَى حَالَيْنِ أَوْ زَمَانَيْنِ: جُمِعَ. فَإِنْ لَمْ يُمْكِنْ: أُخِذَ بِالْأَقْوَى وَالْأَرْجَحِ."]]},{"id":"qa20_6","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ٦","segs":[["matn","وَالتَّرْجِيحُ: إِمَّا فِي الْأَخْبَارِ؛ فَمِنْ ثَلَاثَةِ أَوْجُهٍ: السَّنَدُ: فَيُرَجَّحُ: بِكَثْرَةِ الرُّوَاةِ؛ لِأَنَّهُ أَبْعَدُ مِنَ الْغَلَطِ. وَقَالَ بَعْضُ الْحَنَفِيَّةِ: لَا؛ كَالشَّهَادَةِ. وَبِكَوْنِ رَاوِيهِ أَضْبَطَ وَأَحْفَظَ. وَبِكَوْنِهِ أَوْرَعَ وَأَتْقَى."]]},{"id":"qa20_7","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ٧","segs":[["matn","وَبِكَوْنِهِ صَاحِبَ الْقِصَّةِ، أَوْ مُبَاشِرَهَا دُونَ الْآخَرِ. وَالْمَتْنُ: فَيُرَجَّحُ: بِكَوْنِهِ نَاقِلًا عَنْ حُكْمِ الْأَصْلِ. وَالْمُثْبِتُ أَوْلَى مِنَ النَّافِي. وَالْحَاظِرُ عَلَى الْمُبِيحِ عِنْدَ الْقَاضِي. لَا الْمُسْقِطُ لِلْحَدِّ عَلَى الْمُوجِبِ لَهُ."]]},{"id":"qa20_8","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ٨","segs":[["matn","وَلَا الْمُوجِبُ لِلْحُرِّيَّةِ عَلَى الْمُقْتَضِي لِلرِّقِّ. وَأَمْرٌ مِنْ خَارِجٍ: مِثْلَ: أَنْ يَعْضُدَهُ كِتَابٌ، أَوْ سُنَّةٌ، أَوْ إِجْمَاعٌ، أَوْ قِيَاسٌ. أَوْ يَعْمَلَ بِهِ الْخُلَفَاءُ الْأَرْبَعَةُ. أَوْ صَحَابِيٌّ غَيْرُهُمْ."]]},{"id":"qa20_9","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ٩","segs":[["matn","أَوْ يُخْتَلَفَ عَلَى الرَّاوِي: فَيَقِفَهُ قَوْمٌ، وَيَرْفَعَهُ آخَرُونَ. أَوْ يَنْقُلَ رَاوٍ خِلَافَهُ، فَتَتَعَارَضَ رِوَايَتَاهُ. أَوْ يَكُونَ مَرْفُوعًا وَالْآخَرُ مُرْسَلًا."]]},{"id":"qa20_10","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ١٠","segs":[["matn","وَإِمَّا فِي «الْمَعَانِي»: فَتُرَجَّحُ الْعِلَّةُ: بِمُوَافَقَتِهَا لِدَلِيلٍ آخَرَ مِنْ كِتَابٍ، أَوْ سُنَّةٍ، أَوْ قَوْلِ صَحَابِيٍّ، أَوْ خَبَرٍ مُرْسَلٍ. وَبِكَوْنِهَا نَاقِلَةً عَنْ حُكْمِ الْأَصْلِ. وَرَجَّحَهَا قَوْمٌ: بِخِفَّةِ حُكْمِهَا. وَآخَرُونَ بِثِقَلِهَا."]]},{"id":"qa20_11","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ١١","segs":[["matn","وَهُمَا ضَعِيفَانِ. فَإِنْ كَانَتْ إِحْدَى الْعِلَّتَيْنِ حُكْمًا، وَالْأُخْرَى وَصْفًا حِسِّيًّا: فَرَجَّحَ الْقَاضِي: الثَّانِيَةَ. وَأَبُو الْخَطَّابِ: الْأُولَى. وَبِكَثْرَةِ أُصُولِهَا. وَبِاطِّرَادِهَا وَانْعِكَاسِهَا. وَالْمُتَعَدِّيَةُ عَلَى الْقَاصِرَةِ؛ لِكَثْرَةِ فَائِدَتِهَا. وَمَنَعَ مِنْهُ قَوْمٌ."]]},{"id":"qa20_12","label":"تَرْتِيبُ الْأَدِلَّةِ وَالتَّرْجِيحُ · ١٢","segs":[["matn","وَالْإِثْبَاتُ عَلَى النَّفْيِ. وَالْمُتَّفَقُ عَلَى أَصْلِهِ عَلَى الْمُخْتَلَفِ فِيهِ. وَبِقُوَّةِ الْأَصْلِ فِيمَا لَا يَحْتَمِلُ النَّسْخَ عَلَى مُحْتَمِلِهِ. وَبِكَوْنِهِ رَدَّهُ الشَّارِعُ إِلَيْهِ. وَالْمُؤَثِّرُ عَلَى الْمُلَائِمِ. وَالْمُلَائِمُ عَلَى الْغَرِيبِ. وَالْمُنَاسِبَةُ عَلَى الشَّبَهِيَّةِ."]]}],"group":"الْبَابُ الثَّانِي فِي الْأَدِلَّةِ"},{"id":"qa21","title":"الِاجْتِهَادُ","units":[{"id":"qa21_1","label":"الِاجْتِهَادُ · ١","segs":[["matn","الِاجْتِهَادُ لُغَةً: بَذْلُ الْجُهْدِ فِي فِعْلٍ شَاقٍّ. وَعُرْفًا: بَذْلُ الْجُهْدِ فِي تَعَرُّفِ الْأَحْكَامِ. وَتَمَامُهُ: بَذْلُ الْوُسْعِ فِي الطَّلَبِ إِلَى غَايَتِهِ. وَشَرْطُ الْمُجْتَهِدِ: الْإِحَاطَةُ بِ مَدَارِكِ الْأَحْكَامِ، وَهِيَ الْأُصُولُ الْأَرْبَعَةُ وَالْقِيَاسُ."]]},{"id":"qa21_2","label":"الِاجْتِهَادُ · ٢","segs":[["matn","وَتَرْتِيبِهَا. وَمَا يُعْتَبَرُ لِلْحُكْمِ فِي الْجُمْلَةِ. إِلَّا الْعَدَالَةَ، فَإِنَّ لَهُ الْأَخْذَ بِاجْتِهَادِ نَفْسِهِ، بَلْ هِيَ شَرْطٌ لَقَبُولِ فَتْوَاهُ. فَيَعْرِفُ مِنَ الْكِتَابِ وَالسُّنَّةِ مَا يَتَعَلَّقُ بِالْأَحْكَامِ."]]},{"id":"qa21_3","label":"الِاجْتِهَادُ · ٣","segs":[["matn","فَمِنَ الْقُرْآنِ: قَدْرَ خَمْسِمِائَةِ آيَةٍ، لَا حِفْظُهَا لَفْظًا، بَلْ مَعَانِيهَا؛ لِيَطْلُبَهَا عِنْدَ حَاجَتِهِ. وَمِنَ السُّنَّةِ: مَا هُوَ مُدَوَّنٌ فِي كُتُبِ الْأَئِمَّةِ. وَالنَّاسِخَ وَالْمَنْسُوخَ مِنْهُمَا. وَالصَّحِيحَ وَالضَّعِيفَ مِنَ الْحَدِيثِ؛ لِلتَّرْجِيحِ."]]},{"id":"qa21_4","label":"الِاجْتِهَادُ · ٤","segs":[["matn","وَالْمُجْمَعَ عَلَيْهِ مِنَ الْأَحْكَامِ. وَنَصْبَ الْأَدِلَّةِ وَشُرُوطَهَا. وَمِنَ الْعَرَبِيَّةِ: مَا يُمَيِّزُ بِهِ بَيْنَ صَرِيحِ الْكَلَامِ وَظَاهِرِهِ، وَمُجْمَلِهِ، وَحَقِيقَتِهِ وَمَجَازِهِ، وَعَامِّهِ وَخَاصِّهِ، وَمُحْكَمِهِ وَمُتَشَابِهِهِ، وَمُطْلَقِهِ وَمُقَيَّدِهِ، وَنَصِّهِ وَفَحْوَاهُ."]]},{"id":"qa21_5","label":"الِاجْتِهَادُ · ٥","segs":[["matn","فَإِنْ عَلِمَ ذَلِكَ فِي مَسْأَلَةٍ بِعَيْنِهَا: كَانَ مُجْتَهِدًا فِيهَا، وَإِنْ لَمْ يَعْرِفْ غَيْرَهَا. وَيَجُوزُ: التَّعَبُّدُ بِالِاجْتِهَادِ فِي زَمَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِلْغَائِبِ، وَالْحَاضِرِ بِإِذْنِهِ. وَقِيلَ: لِلْغَائِبِ."]]},{"id":"qa21_6","label":"الِاجْتِهَادُ · ٦","segs":[["matn","وَأَنْ يَكُونَ هُوَ مُتَعَبِّدًا بِهِ فِيمَا لَا وَحْيَ فِيهِ. وَقِيلَ: لَا. لَكِنْ هَلْ وَقَعَ؟ أَنْكَرَهُ بَعْضُ أَصْحَابِنَا، وَأَصْحَابِ الشَّافِعِيِّ، وَأَكْثَرُ الْمُتَكَلِّمِينَ. وَالصَّحِيحُ: بَلَى؛ لِقِصَّةِ أُسَارَى بَدْرٍ وَغَيْرِهَا."]]},{"id":"qa21_7","label":"الِاجْتِهَادُ · ٧","segs":[["matn","وَالْحَقُّ: فِي قَوْلٍ وَاحِدٍ. وَالْمُخْطِئُ فِي الْفُرُوعِ -وَلَا قَاطِعَ-: مَعْذُورٌ، مَأْجُورٌ عَلَى اجْتِهَادِهِ. وَقَالَ بَعْضُ الْمُتَكَلِّمِينَ: كُلُّ مُجْتَهِدٍ مُصِيبٌ، وَلَيْسَ عَلَى الْحَقِّ دَلِيلٌ مَطْلُوبٌ."]]},{"id":"qa21_8","label":"الِاجْتِهَادُ · ٨","segs":[["matn","وَقَالَ بَعْضُهُمْ: وَاخْتُلِفَ فِيهِ عَنْ أَبِي حَنِيفَةَ وَأَصْحَابِهِ. وَزَعَمَ الْجَاحِظُ: أَنَّ مُخَالِفَ الْمِلَّةِ مَتَى عَجَزَ عَنْ دَرَكِ الْحَقِّ؛ فَهُوَ مَعْذُورٌ غَيْرُ آثِمٍ. وَقَالَ الْعَنْبَرِيُّ: كُلُّ مُجْتَهِدٍ مُصِيبٌ فِي الْأُصُولِ وَالْفُرُوعِ."]]},{"id":"qa21_9","label":"الِاجْتِهَادُ · ٩","segs":[["matn","فَإِنْ أَرَادَ: أَنَّهُ أَتَى بِمَا أُمِرَ بِهِ: فَكَقَوْلِ الْجَاحِظِ. وَإِنْ أَرَادَ: فِي نَفْسِ الْأَمْرِ؛ لَزِمَ التَّنَاقُضُ. فَإِنْ تَعَارَضَ عِنْدَهُ دَلِيلَانِ، وَاسْتَوَيَا: تَوَقَّفَ، وَلَمْ يَحْكُمْ بِوَاحِدٍ مِنْهُمَا."]]},{"id":"qa21_10","label":"الِاجْتِهَادُ · ١٠","segs":[["matn","وَقَالَ بَعْضُ الْحَنَفِيَّةِ، وَالشَّافِعِيَّةِ: يُخَيَّرُ. وَلَيْسَ لَهُ أَنْ يَقُولَ: فِيهِ قَوْلَانِ حِكَايَةً عَنْ نَفْسِهِ فِي حَالَةٍ وَاحِدَةٍ. وَإِنْ حُكِيَ ذَلِكَ عَنِ الشَّافِعِيِّ."]]},{"id":"qa21_11","label":"الِاجْتِهَادُ · ١١","segs":[["matn","وَإِذَا اجْتَهَدَ، فَغَلَبَ عَلَى ظَنِّهِ الْحُكْمُ: لَمْ يَجُزِ التَّقْلِيدُ. وَإِنَّمَا يُقَلِّدُ الْعَامِّيُّ. وَمَنْ لَا يَتَمَكَّنُ مِنَ الِاجْتِهَادِ فِي بَعْضِ الْمَسَائِلِ: فَعَامِّيٌّ فِيهَا."]]},{"id":"qa21_12","label":"الِاجْتِهَادُ · ١٢","segs":[["matn","وَالْمُجْتَهِدُ الْمُطْلَقُ: هُوَ الَّذِي صَارَتْ لَهُ الْعُلُومُ خَالِصَةً بِالْقُوَّةِ الْقَرِيبَةِ مِنَ الْفِعْلِ، مِنْ غَيْرِ حَاجَةٍ إِلَى تَعَبٍ كَثِيرٍ، حَتَّى إِذَا نَظَرَ فِي مَسْأَلَةٍ اسْتَقَلَّ بِهَا، وَلَمْ يَحْتَجْ إِلَى غَيْرِهِ."]]},{"id":"qa21_13","label":"الِاجْتِهَادُ · ١٣","segs":[["matn","فَهَذَا؛ قَالَ أَصْحَابُنَا: لَا يُقَلِّدُ مَعَ ضِيقِ الْوَقْتِ وَلَا سَعَتِهِ، وَلَا يُفْتِي بِمَا لَمْ يَنْظُرْ فِيهِ إِلَّا حِكَايَةً عَنْ غَيْرِهِ."]]},{"id":"qa21_14","label":"الِاجْتِهَادُ · ١٤","segs":[["matn","فَإِنْ نَصَّ فِي مَسْأَلَةٍ عَلَى حُكْمٍ، وَعَلَّلَهُ: فَمَذْهَبُهُ فِي كُلِّ مَا وُجِدَتْ فِيهِ تِلْكَ الْعِلَّةُ كَذَلِكَ. فَإِنْ لَمْ يُعَلِّلْ: لَمْ يُخْرَجْ إِلَى مَا أَشْبَهَهَا."]]},{"id":"qa21_15","label":"الِاجْتِهَادُ · ١٥","segs":[["matn","وَكَذَلِكَ: لَا يُنْقَلُ حُكْمُهُ فِي مَسْأَلَتَيْنِ مُتَشَابِهَتَيْنِ كُلُّ وَاحِدَةٍ إِلَى الْأُخْرَى. فَإِنِ اخْتَلَفَ حُكْمُهُ فِي مَسْأَلَةٍ وَاحِدَةٍ، وَجُهِلَ التَّارِيخُ: فَمَذْهَبُهُ أَشْبَهُهُمَا بِأُصُولِهِ وَأَقْوَاهُمَا. وَإِلَّا: فَالثَّانِي؛ لِاسْتِحَالَةِ الْجَمْعِ. وَقَالَ بَعْضُ أَصْحَابِنَا: وَالْأَوَّلُ."]]}],"group":"الْبَابُ الثَّالِثُ فِي الِاجْتِهَادِ وَالتَّقْلِيدِ"},{"id":"qa22","title":"التَّقْلِيدُ","units":[{"id":"qa22_1","label":"التَّقْلِيدُ · ١","segs":[["matn","وَالتَّقْلِيدُ لُغَةً: وَضْعُ الشَّيْءِ فِي الْعُنُقِ مُحِيطًا بِهِ، وَمِنْهُ الْقِلَادَةُ. ثُمَّ اسْتُعْمِلَ فِي تَفْوِيضِ الْأَمْرِ إِلَى الْغَيْرِ؛ كَأَنَّهُ رَبَطَهُ بِعُنُقِهِ. وَاصْطِلَاحًا: قَبُولُ قَوْلِ الْغَيْرِ بِلَا حُجَّةٍ."]]},{"id":"qa22_2","label":"التَّقْلِيدُ · ٢","segs":[["matn","فَيَخْرُجُ: الْأَخْذُ بِقَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ لِأَنَّهُ حُجَّةٌ فِي نَفْسِهِ. وَالْإِجْمَاعُ كَذَلِكَ. ثُمَّ قَالَ أَبُو الْخَطَّابِ: الْعُلُومُ عَلَى ضَرْبَيْنِ: مَا لَا يَسُوغُ فِيهِ التَّقْلِيدُ: كَالْأُصُولِيَّةِ. وَمَا يَسُوغُ: وَهُوَ الْفُرُوعِيَّةُ."]]},{"id":"qa22_3","label":"التَّقْلِيدُ · ٣","segs":[["matn","وَقَالَ بَعْضُ الْقَدَرِيَّةِ: يَلْزَمُ الْعَامِّيَّ النَّظَرُ فِي دَلِيلِ الْفُرُوعِ أَيْضًا. وَهُوَ بَاطِلٌ بِالْإِجْمَاعِ. وَقَالَ أَبُو الْخَطَّابِ: يَلْزَمُهُ مَعْرِفَةُ دَلَائِلِ الْإِسْلَامِ، وَنَحْوِهَا مِمَّا اشْتَهَرَ فَلَا كُلْفَةَ فِيهِ."]]},{"id":"qa22_4","label":"التَّقْلِيدُ · ٤","segs":[["matn","ثُمَّ الْعَامِّيُّ لَا يَسْتَفْتِي إِلَّا مَنْ غَلَبَ عَلَى ظَنِّهِ عِلْمُهُ: لِاشْتِهَارِهِ بِالْعِلْمِ وَالدِّينِ. أَوْ بِخَبَرِ عَدْلٍ بِذَلِكَ. لَا مَنْ عُرِفَ بِالْجَهْلِ. فَإِنْ جَهِلَ حَالَهُ: لَمْ يَسْأَلْهُ. وَقِيلَ: يَجُوزُ."]]},{"id":"qa22_5","label":"التَّقْلِيدُ · ٥","segs":[["matn","فَإِنْ كَانَ فِي الْبَلَدِ مُجْتَهِدُونَ: تَخَيَّرَ. وَقَالَ الْخِرَقِيُّ: الْأَوْثَقَ فِي نَفْسِهِ."]]},{"id":"qa22_6","label":"التَّقْلِيدُ · ٦","segs":[["matn","وَهَذَا آخِرُهُ، وَاللَّهُ تَعَالَى أَعْلَمُ، وَهُوَ الْمُوَفِّقُ، وَلَهُ الْحَمْدُ وَحْدَهُ، وَصَلَوَاتُهُ عَلَى سَيِّدِنَا مُحَمَّدٍ رَسُولِهِ الْمُصْطَفَى وَعَلَى آلِهِ وَصَحْبِهِ، وَسَلَامُهُ."]]}],"group":"الْبَابُ الثَّالِثُ فِي الِاجْتِهَادِ وَالتَّقْلِيدِ"}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
